INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('pres-architectes-premier-appel', 'presentation', (SELECT id FROM sectors WHERE slug = 'architectes'), (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Agence d\'architecture — premier contact', '<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. Nous travaillons avec des agences d\'architecture et des bureaux d\'études sur leur site et leurs outils internes.</p><p>Ce qu\'on entend souvent : beaucoup de bouche-à-oreille, mais peu de projets visibles en ligne.</p><ul><li>Un seul interlocuteur, du premier échange à la mise en ligne</li><li>Un site qui met vos réalisations en valeur avec de vraies photos</li><li>Des prix annoncés dès le départ, un devis écrit sans engagement</li></ul><br><em>Conseil : un nom d\'architecte s\'entend mal au téléphone. Épelez-le une fois, lentement.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('pres-architectes-relance', 'presentation', (SELECT id FROM sectors WHERE slug = 'architectes'), (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'Agence d\'architecture — relance', '<p>Rebonjour {contact}, {prenom_commercial} de Prime Vision Solutions. Je vous avais parlé du site de votre agence.</p><ul><li>Je ne reprends pas tout depuis le début : je viens seulement voir où vous en êtes</li><li>Deux points restaient à trancher : le budget et la partie « projets » du site</li><li>Le devis que je vous ai envoyé est toujours valable, sans engagement</li></ul><br><em>Conseil : proposez un créneau précis en fin de phrase. « Mardi à 14 h » se refuse moins qu\'« un jour ».</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('pres-architectes-closing', 'presentation', (SELECT id FROM sectors WHERE slug = 'architectes'), (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'Agence d\'architecture — closing', '<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. On touche au but sur votre site.</p><ul><li>Le devis est posé, le calendrier aussi</li><li>Il reste une question : c\'est le démarrage ou le découpage en deux paiements ?</li><li>Une fois votre accord, on planifie le premier atelier de photos</li></ul><br><em>Conseil : ne dites jamais « oui » à la place du client. Posez la question et laissez le silence faire son travail.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('pres-artisans-btp-premier-appel', 'presentation', (SELECT id FROM sectors WHERE slug = 'artisans-btp'), (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Artisan ou entreprise du bâtiment — premier contact', '<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. Nous aidons des artisans et des entreprises de rénovation à répondre plus vite à leurs demandes.</p><p>La plupart de ceux qu\'on rencontre reçoivent leurs demandes par téléphone, souvent sur le chantier.</p><ul><li>Un site qui montre vos chantiers, avant et après</li><li>Les demandes de devis qui arrivent au même endroit, sans être perdues</li><li>Des prix annoncés, un devis écrit, le code remis à vous</li></ul><br><em>Conseil : appelez en fin de journée ou à l\'heure du déjeuner. Sur le chantier, personne ne décroche.</em>', 40, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('pres-artisans-btp-relance', 'presentation', (SELECT id FROM sectors WHERE slug = 'artisans-btp'), (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'Artisan ou BTP — relance', '<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. Je reviens vers vous sur le site qu\'on avait évoqué.</p><ul><li>Vous m\'aviez dit que la période était chargée, je comprends très bien</li><li>Ce qui compte pour vous, c\'était surtout de ne plus perdre de demandes</li><li>On peut commencer par la partie la plus simple : la page d\'accueil et le formulaire</li></ul><br><em>Conseil : si la personne est sur un chantier, demandez tout de suite l\'heure du rappel. N\'insistez pas.</em>', 50, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('pres-artisans-btp-closing', 'presentation', (SELECT id FROM sectors WHERE slug = 'artisans-btp'), (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'Artisan ou BTP — closing', '<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. J\'ai le devis sous les yeux, on peut le finaliser ensemble.</p><ul><li>Le périmètre est écrit noir sur blanc, avec le prix exact</li><li>Vous pourrez mettre vos photos de chantier vous-même, sans nous appeler</li><li>Reste à choisir la date de départ : cette semaine ou après les congés ?</li></ul><br><em>Conseil : reformulez le besoin avec ses mots à lui, pas avec les vôtres. C\'est ce qui déclenche la décision.</em>', 60, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('pres-restauration-premier-appel', 'presentation', (SELECT id FROM sectors WHERE slug = 'restauration'), (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Restaurant ou traiteur — premier contact', '<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. Nous travaillons avec des restaurants et des traiteurs sur leur site et leurs réservations.</p><p>Ce qui revient tout le temps : des réservations qui se perdent, et des appels en plein service.</p><ul><li>Une page simple avec la carte, les horaires et la réservation en ligne</li><li>Un assistant qui répond aux questions d\'horaires et d\'accès, même le soir</li><li>Des prix de départ clairs, un devis écrit sans engagement</li></ul><br><em>Conseil : évitez d\'appeler entre midi et 14 h, et après 19 h. Le service passe avant tout.</em>', 70, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('pres-restauration-relance', 'presentation', (SELECT id FROM sectors WHERE slug = 'restauration'), (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'Restaurant ou traiteur — relance', '<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. Je vous avais parlé de la réservation en ligne.</p><ul><li>Je ne vous rappelle pas pour vous embêter : juste pour savoir si le sujet est toujours d\'actualité</li><li>La réservation en ligne peut se brancher sur votre site actuel, sans tout refaire</li><li>Et la carte, vous pourrez la modifier vous-même en deux minutes</li></ul><br><em>Conseil : comparez toujours avec ce qu\'il fait déjà — Google, Instagram, un PDF de carte. Ça le rassure.</em>', 80, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('pres-restauration-closing', 'presentation', (SELECT id FROM sectors WHERE slug = 'restauration'), (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'Restaurant ou traiteur — closing', '<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. On est sur la dernière ligne pour votre site.</p><ul><li>La maquette vous a plu, il ne reste que les photos de plats à récupérer</li><li>Le devis inclut la mise en ligne et la réservation</li><li>Voulez-vous que la mise en ligne se fasse avant ou après votre prochaine carte ?</li></ul><br><em>Conseil : une date de mise en ligne précise vaut mieux qu\'un « dès que possible ».</em>', 90, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('pres-services-b2b-premier-appel', 'presentation', (SELECT id FROM sectors WHERE slug = 'services-b2b'), (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Entreprise de services B2B — premier contact', '<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. Nous équipons des entreprises de services avec un site qui génère des rendez-vous, et des outils pour suivre les devis.</p><p>La plupart de celles qu\'on accompagne perdent des opportunités sans savoir où.</p><ul><li>Un site clair, orienté prise de rendez-vous</li><li>Des relances automatiques sur les devis non signés</li><li>Un seul interlocuteur, un devis écrit sans engagement</li></ul><br><em>Conseil : en B2B, le premier appel sert surtout à obtenir un rendez-vous, pas à vendre le projet.</em>', 100, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('pres-services-b2b-relance', 'presentation', (SELECT id FROM sectors WHERE slug = 'services-b2b'), (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'Services B2B — relance', '<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. Je vous avais envoyé la proposition pour votre site.</p><ul><li>Avez-vous pu la parcourir, ou je vous en résume les deux lignes essentielles ?</li><li>Le budget est celui du devis, et on peut démarrer par une première étape seule</li><li>Ça vous dit qu\'on en parle dix minutes, avec la personne qui valide ?</li></ul><br><em>Conseil : en B2B, demandez toujours qui décide. Un « je dois en parler » arrive très vite.</em>', 110, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('pres-services-b2b-closing', 'presentation', (SELECT id FROM sectors WHERE slug = 'services-b2b'), (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'Services B2B — closing', '<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. On arrive au moment de décider.</p><ul><li>Le devis reprend votre périmètre, le prix et le calendrier</li><li>La livraison se fait par étapes : vous validez chaque palier avant le suivant</li><li>Si tout vous convient, je vous envoie le devis à signer aujourd\'hui</li></ul><br><em>Conseil : après la question finale, ne remplissez pas le silence. Comptez jusqu\'à cinq.</em>', 120, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-premier-appel-1', 'accroche', NULL, (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Ouverture — la question avant le produit', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. Je ne vous appelle pas pour vous vendre un site.\n\nJe voudrais juste comprendre comment vous recevez vos demandes de devis aujourd\'hui. Vous avez deux minutes ?\n<br><em>Conseil : cette accroche marche partout. Elle désarme la méfiance parce qu\'elle annonce d\'emblée qu\'on ne vend rien.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-premier-appel-2', 'accroche', NULL, (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Ouverture — le temps perdu', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nUne question rapide : dans une semaine normale, combien de temps passez-vous à des tâches qui n\'ont rien à voir avec votre métier ?\n<br><em>Conseil : laissez le silence après la question. La première réponse est souvent la vraie.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-premier-appel-3', 'accroche', NULL, (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Ouverture — le client qui cherche', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nQuand un client vous cherche sur Internet en ce moment, qu\'est-ce qu\'il trouve en premier ?\n<br><em>Conseil : notez la réponse mot pour mot. Elle vous servira trois phrases plus loin.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-premier-appel-4', 'accroche', NULL, (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Ouverture — le rendez-vous direct', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. On aide les TPE et PME à recevoir plus de demandes qualifiées.\n\nJe ne vais pas vous prendre plus de deux minutes maintenant. Est-ce qu\'un point de quinze minutes cette semaine serait utile ?\n<br><em>Conseil : ne proposez jamais « quand vous voulez ». Proposez deux créneaux précis.</em>', 40, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-relance-1', 'accroche', NULL, (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'Relance — le rappel du contexte', '{contact}, bonjour, {prenom_commercial} de Prime Vision Solutions. Je vous rappelle comme convenu au sujet de votre site.\n\nVous m\'aviez dit que le sujet était plutôt le budget. On peut en parler très concrètement.\n<br><em>Conseil : rappelez la date exacte du premier échange. « Mardi dernier » prouve que vous avez noté.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-relance-2', 'accroche', NULL, (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'Relance — la question simple', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nJe ne vous appelle pas pour vous relancer, juste pour savoir si le sujet est toujours d\'actualité de votre côté.\n<br><em>Conseil : cette formulation libère le prospect. Un « non » franc vaut mieux qu\'un « peut-être » qui traîne.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-relance-3', 'accroche', NULL, (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'Relance — le devis', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nAvez-vous pu regarder le devis ? Si un point n\'est pas clair, je préfère vous l\'expliquer de vive voix.\n<br><em>Conseil : les trois questions de relance sont presque toujours le prix, le délai et la partie technique.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-relance-4', 'accroche', NULL, (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'Relance — la porte ouverte', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nJe vous avais laissé un message. Si le moment n\'est pas bon, dites-le moi franchement et je vous rappelle quand ça vous arrange.\n<br><em>Conseil : accepter un report n\'est pas perdre la vente. C\'est éviter d\'être celui qui insiste.</em>', 40, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-closing-1', 'accroche', NULL, (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'Closing — la dernière question', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. On y est presque.\n\nIl reste une question à trancher : c\'est plutôt le délai de démarrage ou le paiement en plusieurs fois ?\n<br><em>Conseil : en proposant deux options concrètes, vous transformez un « oui ou non » en « ceci ou cela ».</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-closing-2', 'accroche', NULL, (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'Closing — le récapitulatif', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nJe vous résume en trois phrases : ce qu\'on fait, pour combien, et à partir de quand. Vous me dites si j\'ai bon.\n<br><em>Conseil : terminez le récapitulatif par une question fermée. « C\'est bien ça ? » ouvre la décision.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-closing-3', 'accroche', NULL, (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'Closing — la signature', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nLe devis est prêt à signer. Je peux vous l\'envoyer maintenant, ou vous le déposer en main propre si vous préférez.\n<br><em>Conseil : « envoyer maintenant » est plus simple que « quand vous aurez le temps ».</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-closing-4', 'accroche', NULL, (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'Closing — la porte de sortie honorable', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nSi le projet n\'est pas pour maintenant, dites-le moi : je clôture le dossier proprement, sans vous relancer.\n<br><em>Conseil : cette phrase fait revenir plus de clients qu\'une relance forcée. Elle vous grandit.</em>', 40, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-architectes-premier-appel-1', 'accroche', (SELECT id FROM sectors WHERE slug = 'architectes'), (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Le carnet de commandes invisible', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nLa plupart des agences qu\'on rencontre ont beaucoup de bouche-à-oreille, mais presque rien de visible en ligne. C\'est aussi votre cas ?\n<br><em>Conseil : la question fermée en fin de phrase ouvre la conversation sans mettre la pression.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-architectes-premier-appel-2', 'accroche', (SELECT id FROM sectors WHERE slug = 'architectes'), (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'La question des projets', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nQuand un client potentiel a vu une de vos réalisations, comment il vous contacte ensuite ?\n<br><em>Conseil : écoutez la réponse jusqu\'au bout. Elle révèle souvent un PDF envoyé par mail, ou une page Instagram.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-architectes-premier-appel-3', 'accroche', (SELECT id FROM sectors WHERE slug = 'architectes'), (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Le temps sur les dossiers', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nCombien de temps passez-vous par semaine à chercher un plan, un devis ou un document de dossier ?\n<br><em>Conseil : si la réponse est « trop », ne cherchez pas le chiffre exact. Notez « trop » et avancez.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-architectes-relance-1', 'accroche', (SELECT id FROM sectors WHERE slug = 'architectes'), (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'La relance sur les projets', '{contact}, bonjour, {prenom_commercial} de Prime Vision Solutions.\n\nJe vous avais parlé de la page qui présenterait vos projets. Est-ce que c\'est toujours quelque chose que vous voulez montrer ?\n<br><em>Conseil : posez la question au présent. « Voulez-vous » engage plus que « voudriez-vous ».</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-architectes-relance-2', 'accroche', (SELECT id FROM sectors WHERE slug = 'architectes'), (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'La relance par les photos', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nUne question simple : vos plus belles réalisations, elles sont où aujourd\'hui ? Sur votre téléphone, dans un disque dur ?\n<br><em>Conseil : la réponse est souvent « un peu partout ». C\'est exactement le problème à nommer.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-architectes-relance-3', 'accroche', (SELECT id FROM sectors WHERE slug = 'architectes'), (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'La relance sur la maquette', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nAvez-vous eu le temps de regarder la maquette que je vous ai envoyée ? Je peux passer en agence si c\'est plus simple.\n<br><em>Conseil : une visite de vingt minutes vaut mieux que trois mails. Proposez-la sans hésiter.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-architectes-closing-1', 'accroche', (SELECT id FROM sectors WHERE slug = 'architectes'), (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'La date de démarrage', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nTout est validé côté contenu. Il ne reste que la date : on démarre avant ou après votre prochaine livraison de chantier ?\n<br><em>Conseil : un architecte pense en projets. Ancrez la date sur son calendrier de chantier, pas sur le vôtre.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-architectes-closing-2', 'accroche', (SELECT id FROM sectors WHERE slug = 'architectes'), (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'Les deux points restants', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nIl restait deux points : le budget de la galerie photo et le choix de la langue du site. On les tranche maintenant ?\n<br><em>Conseil : nommez les deux points avant d\'appeler. Un client qui sait ce qui reste décide plus vite.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-architectes-closing-3', 'accroche', (SELECT id FROM sectors WHERE slug = 'architectes'), (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'La signature du devis', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nLe devis est finalisé. Je vous l\'envoie à signer aujourd\'hui, ou vous préférez en parler une dernière fois avec votre associé ?\n<br><em>Conseil : laissez toujours la porte de l\'associé ouverte. Forcer une signature crée un regret.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-artisans-btp-premier-appel-1', 'accroche', (SELECT id FROM sectors WHERE slug = 'artisans-btp'), (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Les demandes perdues', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nBeaucoup d\'artisans reçoivent leurs demandes sur le chantier, et certaines se perdent. Ça vous arrive aussi ?\n<br><em>Conseil : « ça vous arrive aussi » normalise le problème. Personne n\'aime être le seul à mal s\'organiser.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-artisans-btp-premier-appel-2', 'accroche', (SELECT id FROM sectors WHERE slug = 'artisans-btp'), (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Les concurrents en premier', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nQuand un particulier cherche votre métier dans votre ville, il tombe souvent sur ceux qui ont un site à jour. Vous avez un site, vous ?\n<br><em>Conseil : ne dites jamais « vous n\'avez pas de site ». Demandez. La réponse appartient au client.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-artisans-btp-premier-appel-3', 'accroche', (SELECT id FROM sectors WHERE slug = 'artisans-btp'), (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Le devis qui traîne', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nVous faites combien de devis par semaine, et combien vous arrive à relancer vraiment ?\n<br><em>Conseil : la deuxième partie de la question est la plus importante. C\'est là que se trouve l\'argent perdu.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-artisans-btp-relance-1', 'accroche', (SELECT id FROM sectors WHERE slug = 'artisans-btp'), (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'La relance sur le devis', '{contact}, bonjour, {prenom_commercial} de Prime Vision Solutions.\n\nJe vous avais envoyé le devis la semaine dernière. Vous avez eu le temps d\'y jeter un œil ?\n<br><em>Conseil : posez la question au passé (« avez-vous eu le temps ») plutôt qu\'au futur. C\'est plus poli et plus direct.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-artisans-btp-relance-2', 'accroche', (SELECT id FROM sectors WHERE slug = 'artisans-btp'), (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'La relance sur la période', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nVous m\'aviez dit que c\'était chargé en ce moment. Est-ce que la période se calme un peu ?\n<br><em>Conseil : se souvenir d\'une contrainte réelle vaut mille arguments. C\'est ça, la relance utile.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-artisans-btp-relance-3', 'accroche', (SELECT id FROM sectors WHERE slug = 'artisans-btp'), (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'La relance par les photos', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nJe repense à vos chantiers. Vous avez des photos avant / après ? C\'est ce qui rassure le plus un particulier.\n<br><em>Conseil : si la réponse est oui, proposez de les récupérer par téléphone dès aujourd\'hui.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-artisans-btp-closing-1', 'accroche', (SELECT id FROM sectors WHERE slug = 'artisans-btp'), (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'La date et le paiement', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nLe devis est prêt. On démarre la semaine prochaine, et le paiement peut se faire en trois fois. Ça vous convient ?\n<br><em>Conseil : annoncez le paiement en plusieurs fois comme une évidence, pas comme une faveur.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-artisans-btp-closing-2', 'accroche', (SELECT id FROM sectors WHERE slug = 'artisans-btp'), (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'Le récapitulatif', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nJe récapitule : un site avec vos chantiers, un formulaire de devis, et les relances automatiques. Pour le prix du devis. C\'est bien ce qu\'il vous faut ?\n<br><em>Conseil : si le client corrige un point, c\'est bon signe. Il s\'approprie le projet.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-artisans-btp-closing-3', 'accroche', (SELECT id FROM sectors WHERE slug = 'artisans-btp'), (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'La dernière hésitation', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nQu\'est-ce qui vous ferait hésiter encore, à ce stade ? Franchement.\n<br><em>Conseil : « franchement » autorise la vraie réponse. Sans ce mot, vous n\'aurez que la réponse polie.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-restauration-premier-appel-1', 'accroche', (SELECT id FROM sectors WHERE slug = 'restauration'), (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Les appels pendant le service', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nVous recevez beaucoup d\'appels pour des questions simples : horaires, carte, groupes ?\n<br><em>Conseil : à midi, soyez bref. Si la personne est en service, demandez l\'heure du rappel immédiatement.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-restauration-premier-appel-2', 'accroche', (SELECT id FROM sectors WHERE slug = 'restauration'), (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'La réservation du soir', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nDe plus en plus de clients réservent le soir, depuis leur téléphone. Chez vous, la réservation se fait comment aujourd\'hui ?\n<br><em>Conseil : le restaurant est un des rares métiers où le client décide en dehors des heures d\'ouverture.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-restauration-premier-appel-3', 'accroche', (SELECT id FROM sectors WHERE slug = 'restauration'), (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'La carte en ligne', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nQuand vous changez la carte, elle est à jour en ligne dans la journée, ou ça prend plus de temps ?\n<br><em>Conseil : c\'est une des rares douleurs que le restaurateur reconnaît immédiatement.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-restauration-relance-1', 'accroche', (SELECT id FROM sectors WHERE slug = 'restauration'), (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'La relance sur la réservation', '{contact}, bonjour, {prenom_commercial} de Prime Vision Solutions.\n\nJe vous avais parlé de la réservation en ligne. Vous avez pu y réfléchir, ou la période ne s\'y prête pas ?\n<br><em>Conseil : proposer « la période ne s\'y prête pas » donne une sortie honorable. Beaucoup l\'acceptent et reviennent.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-restauration-relance-2', 'accroche', (SELECT id FROM sectors WHERE slug = 'restauration'), (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'La relance par la carte', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nUne idée simple pour commencer : juste la carte et les horaires à jour, sans tout refaire. Ça vous intéresse ?\n<br><em>Conseil : un petit périmètre fait démarrer plus de projets qu\'un grand devis. On agrandit ensuite.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-restauration-relance-3', 'accroche', (SELECT id FROM sectors WHERE slug = 'restauration'), (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'La relance après la carte', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nVous m\'aviez dit que la nouvelle carte arrivait bientôt. Elle est sortie ?\n<br><em>Conseil : s\'appuyer sur un événement réel du restaurant (nouvelle carte, terrasse, saison) rend l\'appel naturel.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-restauration-closing-1', 'accroche', (SELECT id FROM sectors WHERE slug = 'restauration'), (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'La mise en ligne', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nLe site est prêt. On met en ligne avant ou après votre prochaine carte ?\n<br><em>Conseil : pour un restaurant, le calendrier des cartes est le vrai calendrier du projet.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-restauration-closing-2', 'accroche', (SELECT id FROM sectors WHERE slug = 'restauration'), (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'Les photos de plats', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nIl ne manque que les photos de plats. Vous les avez, ou on prend une heure avec un photographe ?\n<br><em>Conseil : proposez toujours une solution simple. Une photo au téléphone bien cadrée vaut mieux qu\'un report.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-restauration-closing-3', 'accroche', (SELECT id FROM sectors WHERE slug = 'restauration'), (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'La décision', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nTout est calé : le site, la réservation, le prix. Je vous envoie le devis à signer aujourd\'hui ?\n<br><em>Conseil : le restaurateur décide vite quand tout est concret. Évitez les détails techniques à ce stade.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-services-b2b-premier-appel-1', 'accroche', (SELECT id FROM sectors WHERE slug = 'services-b2b'), (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Le pipeline invisible', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nLa plupart des entreprises de services qu\'on accompagne savent qu\'elles perdent des opportunités, mais pas où. Ça vous parle ?\n<br><em>Conseil : en B2B, parlez « d\'opportunités » plutôt que de « demandes ». Le vocabulaire compte.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-services-b2b-premier-appel-2', 'accroche', (SELECT id FROM sectors WHERE slug = 'services-b2b'), (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Le temps commercial', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nVos commerciaux passent-ils du temps à faire du suivi administratif au lieu de vendre ?\n<br><em>Conseil : la question est fermée exprès. Un « oui » suffit à ouvrir tout le reste de l\'appel.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-services-b2b-premier-appel-3', 'accroche', (SELECT id FROM sectors WHERE slug = 'services-b2b'), (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Le premier rendez-vous', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nCombien de rendez-vous qualifiés recevez-vous par mois, et d\'où viennent-ils ?\n<br><em>Conseil : demandez toujours « d\'où viennent-ils ». C\'est là que se cache le vrai problème.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-services-b2b-relance-1', 'accroche', (SELECT id FROM sectors WHERE slug = 'services-b2b'), (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'La relance sur la proposition', '{contact}, bonjour, {prenom_commercial} de Prime Vision Solutions.\n\nJe vous avais envoyé la proposition. Je peux vous en faire un résumé en deux minutes, si c\'est plus rapide.\n<br><em>Conseil : offrir le résumé évite le « je n\'ai pas eu le temps de lire ». C\'est presque toujours la vraie raison.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-services-b2b-relance-2', 'accroche', (SELECT id FROM sectors WHERE slug = 'services-b2b'), (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'La relance sur le décideur', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nPour que le projet avance, il faudrait peut-être inclure la personne qui valide le budget. Vous voyez un créneau à trois ?\n<br><em>Conseil : ne dites jamais « votre associé ». Demandez « la personne qui valide le budget ».</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-services-b2b-relance-3', 'accroche', (SELECT id FROM sectors WHERE slug = 'services-b2b'), (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'La relance par étape', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nOn pourrait démarrer par une seule partie : la page de prise de rendez-vous. Le reste attendrait le mois prochain. Ça vous aiderait ?\n<br><em>Conseil : découper un projet fait baisser le risque perçu. C\'est souvent ce qui débloque un dossier.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-services-b2b-closing-1', 'accroche', (SELECT id FROM sectors WHERE slug = 'services-b2b'), (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'La décision finale', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nLe devis reprend le périmètre, le prix et le calendrier. Vous le signez cette semaine, ou il manque encore une information ?\n<br><em>Conseil : « ou il manque une information » permet au client de dire ce qui bloque vraiment.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-services-b2b-closing-2', 'accroche', (SELECT id FROM sectors WHERE slug = 'services-b2b'), (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'La validation à chaque étape', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nVous validez chaque étape avant la suivante. Donc rien ne vous engage au-delà de ce que vous avez vu. Ça vous rassure ?\n<br><em>Conseil : en B2B, le risque perçu est le premier frein. Parlez livraison par étapes avant le prix.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('acc-services-b2b-closing-3', 'accroche', (SELECT id FROM sectors WHERE slug = 'services-b2b'), (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'La date de démarrage', 'Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions.\n\nSi on signe cette semaine, on démarre lundi. Après, le prochain créneau est dans trois semaines. Vous préférez quoi ?\n<br><em>Conseil : un vrai créneau de disponibilité n\'est pas une fausse urgence. Ne l\'inventez jamais, vérifiez-le.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('barr-1', 'barrage', NULL, NULL, NULL, 'Le bon interlocuteur, sans détour', 'Bonjour, {prenom_commercial} de Prime Vision Solutions. Je cherche la personne qui s\'occupe de la partie site Internet chez {entreprise_client}. Vous savez qui c\'est ?\n<br><em>Conseil : demandez le nom, pas la fonction. Un nom crée un lien direct pour la suite de l\'appel.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('barr-2', 'barrage', NULL, NULL, NULL, 'Le message clair', 'Bonjour, {prenom_commercial} de Prime Vision Solutions. Je vous appelle au sujet du site de {entreprise_client}. Vous pouvez me passer la direction, s\'il vous plaît ?\n<br><em>Conseil : dites la raison de l\'appel en une phrase. Un standard bloque ce qu\'il ne comprend pas.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('barr-3', 'barrage', NULL, NULL, NULL, 'Quand le barrage demande « c\'est à quel sujet ? »', 'Bien sûr. Il s\'agit de leur présence sur Internet : comment leurs clients les trouvent aujourd\'hui. C\'est un appel de deux minutes, sans vente forcée.\n<br><em>Conseil : « sans vente forcée » change le ton de l\'échange. Le standard devient un allié.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('barr-4', 'barrage', NULL, NULL, NULL, 'Le dirigeant absent', 'Merci. Du coup, il vaut mieux que je le rappelle. C\'est plus simple pour lui à quel moment : le matin ou en fin de journée ?\n<br><em>Conseil : demandez le meilleur créneau, jamais l\'heure à laquelle il est là « en général ».</em>', 40, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('barr-5', 'barrage', NULL, NULL, NULL, 'Le refus poli du standard', 'Je comprends, vous faites votre travail. Juste une chose : pouvez-vous me dire à qui envoyer un mail plutôt qu\'appeler ? Je ne vais pas insister par téléphone.\n<br><em>Conseil : proposer le mail désamorce la méfiance et laisse une trace écrite de votre passage.</em>', 50, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('barr-6', 'barrage', NULL, NULL, NULL, 'Le retour après un premier échange', 'Bonjour, {prenom_commercial} de Prime Vision Solutions. J\'ai déjà échangé avec {contact} au sujet de leur site, je rappelle comme convenu. Il est disponible ?\n<br><em>Conseil : citez le nom du contact dès la première phrase. C\'est ce qui fait passer du statut d\'inconnu à celui d\'attendu.</em>', 60, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('repond-1', 'repondeur', NULL, NULL, NULL, 'Répondeur — premier appel', 'Bonjour, c\'est {prenom_commercial} de Prime Vision Solutions. Je vous appelle au sujet du site de {entreprise_client}. Je rappelle demain matin. Bonne journée.\n<br><em>Conseil : 15 secondes, pas une de plus. Ne dites pas tout, le but est qu\'on vous rappelle.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('repond-2', 'repondeur', NULL, NULL, NULL, 'Répondeur — après un échange', 'Bonjour, {prenom_commercial} de Prime Vision Solutions. Je reviens vers vous comme convenu pour faire le point sur votre projet. Vous avez mon numéro. À bientôt.\n<br><em>Conseil : laissez le numéro une seule fois et lentement. Un numéro répété trois fois sonne comme un message publicitaire.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('dec-site-web-1', 'decouverte', NULL, NULL, (SELECT id FROM services WHERE slug = 'site-web'), 'Site web — les questions, dans l\'ordre', '<p>Posez-les dans cet ordre, puis arrêtez-vous : quatre bonnes réponses suffisent pour proposer.</p><ul><li>Aujourd\'hui, comment vos clients vous trouvent-ils ?<br><em>Conseil : vous saurez si le site est un canal réel ou un simple panneau.</em></li><li>Quand quelqu\'un vous cherche sur Google, il tombe sur quoi ?<br><em>Conseil : c\'est la question qui révèle le problème le plus fréquent : un site absent ou daté.</em></li><li>Qu\'est-ce qui manque le plus à votre site actuel ?<br><em>Conseil : laissez le prospect formuler le besoin. Vous n\'aurez pas à le convaincre.</em></li><li>Combien de demandes recevez-vous par mois, à peu près ?<br><em>Conseil : un ordre de grandeur suffit, pas un chiffre exact.</em></li><li>Qui met à jour les textes et les photos, aujourd\'hui ?<br><em>Conseil : si c\'est un prestataire, le client est dépendant. C\'est un point de douleur.</em></li><li>Sur téléphone, votre site s\'affiche bien ?<br><em>Conseil : beaucoup répondent « je crois ». Proposez de regarder ensemble, c\'est parlant.</em></li><li>Si vous refaisiez le site, qu\'est-ce qui changerait pour vous ?<br><em>Conseil : la réponse donne le vrai critère de décision : plus de demandes, plus de crédibilité, ou du temps.</em></li></ul>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('dec-application-1', 'decouverte', NULL, NULL, (SELECT id FROM services WHERE slug = 'application'), 'Application sur mesure — les questions, dans l\'ordre', '<p>Ici, on cherche surtout le processus manuel qui coûte du temps. Écoutez les mots du métier.</p><ul><li>Comment vous organisez-vous aujourd\'hui : tableur, cahier, logiciel ?<br><em>Conseil : c\'est le point de départ réel de tout projet d\'application.</em></li><li>Combien de tableurs différents utilisez-vous, à peu près ?<br><em>Conseil : plus il y en a, plus la douleur est facile à montrer.</em></li><li>Qui doit voir les informations, et qui ne doit pas ?<br><em>Conseil : les droits d\'accès font partie du besoin, même si le client n\'y pense pas.</em></li><li>Quelle tâche refaites-vous plusieurs fois par jour ?<br><em>Conseil : c\'est là que se trouve le gain de temps le plus visible.</em></li><li>Ça vous arrive de ressaisir la même information deux fois ?<br><em>Conseil : question simple, réponse presque toujours oui. Elle fait mouche.</em></li><li>Avez-vous un outil que vous devez garder absolument ?<br><em>Conseil : comptabilité, caisse, CRM. Cela conditionne les connexions à prévoir.</em></li><li>Sur téléphone, tablette ou ordinateur : où travaillez-vous le plus ?<br><em>Conseil : une application terrain et une application de bureau ne se conçoivent pas pareil.</em></li><li>Si vous gagniez une heure par jour, qu\'est-ce que vous en feriez ?<br><em>Conseil : la réponse relie le projet à un bénéfice concret, pas à de l\'informatique.</em></li></ul>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('dec-automatisation-ia-1', 'decouverte', NULL, NULL, (SELECT id FROM services WHERE slug = 'automatisation-ia'), 'Automatisation IA — les questions, dans l\'ordre', '<p>L\'objectif est de trouver UNE tâche répétitive, pas de cartographier toute l\'entreprise.</p><ul><li>Quelles tâches vous prennent le plus de temps chaque semaine ?<br><em>Conseil : notez-les telles quelles, avec les mots du client.</em></li><li>Combien de demandes arrivent par mail, formulaire ou téléphone ?<br><em>Conseil : le volume justifie l\'automatisation. Sans volume, rien ne se rentabilise.</em></li><li>Qui traite ces demandes, et à quel moment de la journée ?<br><em>Conseil : vous découvrez souvent que tout repose sur une seule personne.</em></li><li>Que se passe-t-il si une demande attend 48 heures ?<br><em>Conseil : la réponse chiffre le coût de l\'inaction, sans que vous ayez à l\'inventer.</em></li><li>Quelles informations recopiez-vous d\'un outil à l\'autre ?<br><em>Conseil : c\'est le candidat idéal pour une première automatisation simple.</em></li><li>Qui doit valider avant qu\'un message part ?<br><em>Conseil : le client a besoin d\'un contrôle humain. Proposez-le avant qu\'il le demande.</em></li><li>Avez-vous déjà essayé d\'automatiser quelque chose ? Qu\'est-ce qui a bloqué ?<br><em>Conseil : un échec passé explique souvent une méfiance. Il faut l\'entendre.</em></li></ul>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('dec-chatbot-ia-1', 'decouverte', NULL, NULL, (SELECT id FROM services WHERE slug = 'chatbot-ia'), 'Chatbot IA — les questions, dans l\'ordre', '<p>Le chatbot se vend sur les questions qui reviennent, pas sur la technologie.</p><ul><li>Quelles questions reviennent le plus souvent de la part de vos clients ?<br><em>Conseil : trois ou quatre questions suffisent à construire un premier assistant utile.</em></li><li>Combien d\'appels par jour pour ces questions-là ?<br><em>Conseil : c\'est le temps que l\'assistant rendra à l\'équipe.</em></li><li>Que se passe-t-il le soir et le week-end, quand vous êtes fermé ?<br><em>Conseil : chaque message sans réponse est une demande perdue, sans que vous ayez à la chiffrer.</em></li><li>Qui répond aux messages du site aujourd\'hui ?<br><em>Conseil : souvent personne. C\'est l\'argument le plus simple du chatbot.</em></li><li>Sur quelles informations l\'assistant peut-il s\'appuyer sans se tromper ?<br><em>Conseil : horaires, tarifs de départ, zone d\'intervention : il ne répondra qu\'à ça.</em></li><li>Quand un client doit-il parler à un humain, selon vous ?<br><em>Conseil : vous préparez la règle de passage à l\'humain avec le client lui-même.</em></li><li>Ça vous gênerait qu\'un assistant réponde la nuit à votre place ?<br><em>Conseil : posez la question franchement. La réponse dit si le projet est mûr.</em></li></ul>', 40, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('dec-architectes-1', 'decouverte', (SELECT id FROM sectors WHERE slug = 'architectes'), NULL, NULL, 'Questions propres aux architectes et bureaux d\'études', '<p>Trois questions pour entrer dans le quotidien d\'une agence.</p><ul><li>Combien de projets en cours avez-vous en ce moment ?<br><em>Conseil : un architecte jauge sa charge en projets, pas en mois. Parlez son langage.</em></li><li>Où sont vos réalisations aujourd\'hui : site, Instagram, PDF ?<br><em>Conseil : c\'est la première question à laquelle un projet de site répond.</em></li><li>Sur un dossier, combien de temps passez-vous à chercher des documents ?<br><em>Conseil : une agence qui perd du temps sur les plans est un client pour un espace projet.</em></li></ul>', 50, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('dec-artisans-btp-1', 'decouverte', (SELECT id FROM sectors WHERE slug = 'artisans-btp'), NULL, NULL, 'Questions propres aux artisans et au BTP', '<p>Trois questions pour parler chantier, sans jargon.</p><ul><li>Combien de demandes de devis par semaine, et en combien de temps vous y répondez ?<br><em>Conseil : le délai de réponse est le premier facteur de signature dans ce métier.</em></li><li>Vous relancez les devis qui n\'ont pas de réponse ?<br><em>Conseil : la plupart ne relancent pas, faute de temps. C\'est le sujet à travailler.</em></li><li>Vous travaillez dans un rayon de combien de kilomètres ?<br><em>Conseil : la zone d\'intervention détermine les pages et le référencement local à prévoir.</em></li></ul>', 60, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('dec-restauration-1', 'decouverte', (SELECT id FROM sectors WHERE slug = 'restauration'), NULL, NULL, 'Questions propres aux restaurants', '<p>Trois questions à poser hors service, jamais à midi.</p><ul><li>Combien d\'appels par jour pour des réservations ?<br><em>Conseil : c\'est le volume que la réservation en ligne ou l\'assistant peuvent absorber.</em></li><li>Combien de couverts par service en moyenne ?<br><em>Conseil : un restaurant qui remplit déjà ne cherche pas plus de clients, mais moins de travail.</em></li><li>Votre carte en ligne, elle est à jour ?<br><em>Conseil : un client qui trouve une carte périmée part souvent. Le sujet est très concret.</em></li></ul>', 70, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('dec-services-b2b-1', 'decouverte', (SELECT id FROM sectors WHERE slug = 'services-b2b'), NULL, NULL, 'Questions propres aux services B2B', '<p>Trois questions pour qualifier vite un dossier.</p><ul><li>Combien de rendez-vous qualifiés par mois ?<br><em>Conseil : c\'est la mesure qui compte pour une entreprise de services.</em></li><li>Combien de temps entre le premier contact et la signature ?<br><em>Conseil : un cycle long demande des relances. Un cycle court demande un site qui convertit.</em></li><li>Qui suit les devis, et avec quel outil ?<br><em>Conseil : un suivi dans une boîte mail est un signal d\'automatisation.</em></li></ul>', 80, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('dec-relance-1', 'decouverte', NULL, (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'Découverte — en relance', '<p>En relance, on ne redécouvre pas : on précise ce qui bloque.</p><ul><li>Est-ce que le devis correspond à ce que vous attendiez ?<br><em>Conseil : si la réponse est non, tout le reste de l\'appel porte sur l\'écart.</em></li><li>Qu\'est-ce qui vous freine encore : le budget, le délai, la technique ?<br><em>Conseil : en proposant trois pistes, vous obtenez la vraie plus vite.</em></li><li>Qui d\'autre doit valider, et quand peut-on l\'inclure ?<br><em>Conseil : tant que le décideur n\'est pas là, la relance tourne en rond.</em></li><li>Si on commence la semaine prochaine, c\'est jouable ?<br><em>Conseil : une question de calendrier révèle plus qu\'une question de motivation.</em></li></ul>', 90, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('dec-closing-1', 'decouverte', NULL, (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'Découverte — en closing', '<p>Trois questions maximum. Au closing, on ne découvre plus, on verrouille.</p><ul><li>Reste-t-il un point qui vous empêche de signer aujourd\'hui ?<br><em>Conseil : la question est directe. Elle fait gagner deux appels.</em></li><li>Le montant du devis est-il validé de votre côté ?<br><em>Conseil : ne supposez jamais que le budget est acquis.</em></li><li>On cale le démarrage sur quelle date ?<br><em>Conseil : une date dans la conversation vaut mieux qu\'une date dans un mail.</em></li></ul>', 100, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('arg-site-web-architectes', 'argumentaire', (SELECT id FROM sectors WHERE slug = 'architectes'), NULL, (SELECT id FROM services WHERE slug = 'site-web'), 'Argumentaire — Site web · Architectes', '<p>Ce que ça change concrètement chez ce type d\'entreprise :</p><ul><li>Quand un maître d\'ouvrage cherche un architecte dans votre ville, il compare trois sites. Le vôtre doit montrer vos projets avant même qu\'il vous appelle.<br><em>Conseil : un site d\'architecte n\'a pas besoin d\'être grand : il doit être beau et à jour.</em></li><li>Une page par projet, avec les photos, le programme et le lieu. C\'est ce que regarde un client avant de vous contacter.<br><em>Conseil : une galerie sans texte ne convertit pas. Une fiche projet par réalisation, oui.</em></li><li>Vos photos sont probablement votre meilleur argument. Sur le site, elles sont protégées et elles vous appartiennent.<br><em>Conseil : Instagram reste utile, mais il ne remplace pas un site. Les deux se complètent.</em></li><li>Vous mettez à jour vos projets vous-même, sans dépendre d\'un prestataire. Une nouvelle livraison s\'ajoute en quelques minutes.<br><em>Conseil : montrez l\'interface d\'administration côté client, c\'est rassurant.</em></li></ul>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('arg-site-web-artisans-btp', 'argumentaire', (SELECT id FROM sectors WHERE slug = 'artisans-btp'), NULL, (SELECT id FROM services WHERE slug = 'site-web'), 'Argumentaire — Site web · Artisans et BTP', '<p>Ce que ça change concrètement chez ce type d\'entreprise :</p><ul><li>Un particulier qui cherche un artisan dans sa ville lit trois choses : vos réalisations, vos avis et vos garanties. Le site les met côte à côte.<br><em>Conseil : parlez de « rassurer », pas de « crédibilité ». C\'est le mot juste.</em></li><li>Un formulaire de demande de devis en trente secondes. Pas cinq écrans, pas de compte à créer.<br><em>Conseil : chaque champ en trop fait perdre des demandes.</em></li><li>Une page par grand chantier type : salle de bain, toiture, extension. C\'est ce que les gens tapent sur Google.<br><em>Conseil : c\'est concret et ça se comprend immédiatement.</em></li><li>Quand vous envoyez un devis, le client peut le relire sur son téléphone. Le lien remplace le PDF illisible.<br><em>Conseil : un devis lisible réduit les allers-retours au téléphone.</em></li></ul>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('arg-site-web-restauration', 'argumentaire', (SELECT id FROM sectors WHERE slug = 'restauration'), NULL, (SELECT id FROM services WHERE slug = 'site-web'), 'Argumentaire — Site web · Restauration', '<p>Ce que ça change concrètement chez ce type d\'entreprise :</p><ul><li>La carte toujours à jour, sans réimprimer et sans appel à votre prestataire. Vous changez un plat, le site suit.<br><em>Conseil : c\'est l\'argument qui parle le plus vite aux restaurateurs.</em></li><li>La réservation en ligne, y compris le soir et le week-end, quand vous êtes en service ou fermé.<br><em>Conseil : le client décide en dehors des horaires d\'ouverture.</em></li><li>Horaires, accès, stationnement, groupes : les réponses aux questions que vous répétez cent fois.<br><em>Conseil : chaque question évitée, c\'est une minute de service gagnée.</em></li><li>Un site rapide sur téléphone. Un client affamé ne patiente pas trois secondes.<br><em>Conseil : la vitesse se montre, elle ne s\'explique pas. Testez devant le client.</em></li></ul>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('arg-site-web-services-b2b', 'argumentaire', (SELECT id FROM sectors WHERE slug = 'services-b2b'), NULL, (SELECT id FROM services WHERE slug = 'site-web'), 'Argumentaire — Site web · Services B2B', '<p>Ce que ça change concrètement chez ce type d\'entreprise :</p><ul><li>Aujourd\'hui quand un prospect vous cherche sur Google, il doit comprendre en dix secondes ce que vous faites et pour qui.<br><em>Conseil : la clarté est plus rentable que l\'esthétique en B2B.</em></li><li>Un bouton de prise de rendez-vous visible partout. C\'est la seule action que vous voulez vraiment.<br><em>Conseil : un seul appel à l\'action par page. Deux actions, c\'est zéro action.</em></li><li>Une page par métier ou par secteur. Une page unique « nos services » ne se positionne sur rien.<br><em>Conseil : en B2B, les acheteurs tapent leur problème, pas votre métier.</em></li><li>Vous voyez ce qui fonctionne : visites, demandes, pages consultées. Sans outil compliqué.<br><em>Conseil : parlez d\'analytics respectueuses de la vie privée, c\'est vrai et ça rassure.</em></li></ul>', 40, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('arg-application-architectes', 'argumentaire', (SELECT id FROM sectors WHERE slug = 'architectes'), NULL, (SELECT id FROM services WHERE slug = 'application'), 'Argumentaire — Application · Architectes', '<p>Ce que ça change concrètement chez ce type d\'entreprise :</p><ul><li>Aujourd\'hui quand vous cherchez un plan dans un dossier, vous ouvrez combien de dossiers avant de le trouver ? Supprimez cette recherche.<br><em>Conseil : le problème est très concret. Ne parlez pas de « GED ».</em></li><li>Un espace projet par chantier : plans, comptes rendus, documents partagés avec le maître d\'ouvrage. Chacun voit ce qui le concerne.<br><em>Conseil : la notion de droits par personne est bien comprise par les architectes.</em></li><li>Les réserves et les allers-retours de chantier sont notés au même endroit, avec une photo et une date.<br><em>Conseil : c\'est un besoin qui revient dans toutes les agences.</em></li><li>Sur le chantier, vous ouvrez le dossier sur votre téléphone. Pas besoin de revenir au bureau.<br><em>Conseil : le terrain est le lieu de décision, pas le bureau.</em></li></ul>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('arg-application-artisans-btp', 'argumentaire', (SELECT id FROM sectors WHERE slug = 'artisans-btp'), NULL, (SELECT id FROM services WHERE slug = 'application'), 'Argumentaire — Application · Artisans et BTP', '<p>Ce que ça change concrètement chez ce type d\'entreprise :</p><ul><li>Aujourd\'hui quand une demande arrive et que vous êtes sur un chantier, elle attend. Avec l\'application, elle arrive au même endroit, avec une photo et une adresse.<br><em>Conseil : l\'objectif : une seule boîte, pas trois.</em></li><li>Vos devis se créent depuis une bibliothèque de prix. Vous ajustez, vous envoyez, le client signe en ligne.<br><em>Conseil : la bibliothèque de prix fait gagner du temps dès le deuxième devis.</em></li><li>Les relances partent toutes seules au bout de sept jours. Vous ne perdez plus un devis dans un carnet.<br><em>Conseil : la relance automatique est souvent le gain le plus immédiat.</em></li><li>Le planning de l\'équipe est visible sur téléphone. Chacun sait où il va demain matin.<br><em>Conseil : une photo du planning sur le téléphone parle mieux qu\'un tableau Excel.</em></li></ul>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('arg-application-restauration', 'argumentaire', (SELECT id FROM sectors WHERE slug = 'restauration'), NULL, (SELECT id FROM services WHERE slug = 'application'), 'Argumentaire — Application · Restauration', '<p>Ce que ça change concrètement chez ce type d\'entreprise :</p><ul><li>Une seule application pour les réservations, les commandes et les stocks, au lieu d\'un cahier et de deux tableurs.<br><em>Conseil : ne dites pas « ERP ». Dites « un seul endroit ».</em></li><li>Le plan de salle se remplit en direct. Le serveur voit les tables libres sans faire le tour de la salle.<br><em>Conseil : c\'est un gain visible dès le premier service.</em></li><li>Les stocks se décrémentent avec les plats vendus. Vous savez ce qui manque avant d\'ouvrir.<br><em>Conseil : la question « qu\'est-ce que je commande demain » se règle en dix secondes.</em></li><li>La réservation vient du site, de Google et du téléphone, toujours dans le même planning.<br><em>Conseil : éviter la double réservation est le vrai gain, avant la statistique.</em></li></ul>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('arg-application-services-b2b', 'argumentaire', (SELECT id FROM sectors WHERE slug = 'services-b2b'), NULL, (SELECT id FROM services WHERE slug = 'application'), 'Argumentaire — Application · Services B2B', '<p>Ce que ça change concrètement chez ce type d\'entreprise :</p><ul><li>Aujourd\'hui votre suivi de devis est dans une boîte mail. Un tableau simple remplacerait déjà trois heures par semaine.<br><em>Conseil : commencez petit : un tableau partagé convainc plus qu\'une refonte.</em></li><li>Chaque devis a son statut : envoyé, relancé, signé, perdu. Vous voyez d\'un coup d\'œil ce qui dort.<br><em>Conseil : c\'est le mot « dort » qui déclenche la prise de conscience.</em></li><li>Les relances partent automatiquement aux dates que vous choisissez. Rien ne s\'oublie.<br><em>Conseil : un commercial relance mieux quand il n\'a pas à y penser.</em></li><li>Vos commerciaux saisissent sur téléphone entre deux rendez-vous, et le bureau voit tout en direct.<br><em>Conseil : la saisie mobile est souvent le point de bascule d\'un projet.</em></li></ul>', 40, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('arg-automatisation-ia-architectes', 'argumentaire', (SELECT id FROM sectors WHERE slug = 'architectes'), NULL, (SELECT id FROM services WHERE slug = 'automatisation-ia'), 'Argumentaire — Automatisation IA · Architectes', '<p>Ce que ça change concrètement chez ce type d\'entreprise :</p><ul><li>Aujourd\'hui quand un nouveau message arrive, quelqu\'un le lit, le trie, puis le recopie dans le dossier. Cette chaîne peut se faire seule.<br><em>Conseil : décrivez la chaîne en trois étapes, comme ici. C\'est limpide.</em></li><li>Les comptes rendus de réunion se préparent à partir de vos notes. Vous relisez et vous validez.<br><em>Conseil : il y a toujours une validation humaine. Dites-le avant qu\'on vous le demande.</em></li><li>Les relances d\'avenant et de facture partent à date fixe, sans y penser.<br><em>Conseil : c\'est l\'exemple qui parle le plus aux petites structures.</em></li><li>Les demandes entrantes sont classées par type de projet avant même que vous les ouvriez.<br><em>Conseil : on ne parle pas d\'IA ici, on parle de tri. C\'est plus vendeur.</em></li></ul>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('arg-automatisation-ia-artisans-btp', 'argumentaire', (SELECT id FROM sectors WHERE slug = 'artisans-btp'), NULL, (SELECT id FROM services WHERE slug = 'automatisation-ia'), 'Argumentaire — Automatisation IA · Artisans et BTP', '<p>Ce que ça change concrètement chez ce type d\'entreprise :</p><ul><li>Quand un particulier remplit le formulaire, la demande devient une fiche, avec un SMS de confirmation et une alerte pour vous.<br><em>Conseil : le premier automatisme à mettre en place, dans presque tous les cas.</em></li><li>Le devis non signé reçoit une relance polie au bout de sept jours, puis quatorze. Vous n\'y pensez plus.<br><em>Conseil : c\'est souvent le gain le plus direct en chiffre d\'affaires.</em></li><li>Les photos du chantier arrivent dans le bon dossier, sans passer par WhatsApp.<br><em>Conseil : le vrai problème des artisans, c\'est où sont les photos.</em></li><li>La facture se prépare à partir du devis signé. Vous vérifiez les montants, puis vous envoyez.<br><em>Conseil : la facture est le document que tout le monde déteste faire.</em></li></ul>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('arg-automatisation-ia-restauration', 'argumentaire', (SELECT id FROM sectors WHERE slug = 'restauration'), NULL, (SELECT id FROM services WHERE slug = 'automatisation-ia'), 'Argumentaire — Automatisation IA · Restauration', '<p>Ce que ça change concrètement chez ce type d\'entreprise :</p><ul><li>Chaque réservation reçoit une confirmation, un rappel la veille, et une demande d\'avis le lendemain. Tout se fait sans vous.<br><em>Conseil : c\'est simple et ça réduit vraiment le nombre de réservations perdues.</em></li><li>Les commandes de fournisseurs se préparent à partir des stocks bas. Vous validez avant envoi.<br><em>Conseil : un restaurant qui commande à la main commande trop ou trop peu.</em></li><li>Les avis clients arrivent au même endroit, prêts à être repris sur le site.<br><em>Conseil : les avis sont un moteur de réservation, encore faut-il les collecter.</em></li><li>La carte du site se met à jour depuis un simple fichier. Une modification, une sauvegarde, c\'est fini.<br><em>Conseil : zéro dépendance au prestataire : c\'est ce qu\'il veut entendre.</em></li></ul>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('arg-automatisation-ia-services-b2b', 'argumentaire', (SELECT id FROM sectors WHERE slug = 'services-b2b'), NULL, (SELECT id FROM services WHERE slug = 'automatisation-ia'), 'Argumentaire — Automatisation IA · Services B2B', '<p>Ce que ça change concrètement chez ce type d\'entreprise :</p><ul><li>Aujourd\'hui votre commercial recopie les informations d\'un formulaire dans son CRM. Cette étape disparaît.<br><em>Conseil : la double saisie est le premier gain accepté par les équipes commerciales.</em></li><li>Les rendez-vous pris en ligne arrivent dans vos agendas, avec un rappel automatique la veille.<br><em>Conseil : moins de rendez-vous manqués, sans relance manuelle.</em></li><li>Le devis signé déclenche la facture et l\'ouverture du dossier projet. Personne n\'oublie.<br><em>Conseil : la chaîne devis-facture-projet est ce que les PME demandent le plus.</em></li><li>Un rapport hebdomadaire se construit seul à partir de vos outils. Vous le recevez le lundi matin.<br><em>Conseil : un rapport qui arrive tout seul, c\'est un rituel d\'équipe en plus.</em></li></ul>', 40, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('arg-chatbot-ia-architectes', 'argumentaire', (SELECT id FROM sectors WHERE slug = 'architectes'), NULL, (SELECT id FROM services WHERE slug = 'chatbot-ia'), 'Argumentaire — Chatbot IA · Architectes', '<p>Ce que ça change concrètement chez ce type d\'entreprise :</p><ul><li>Le soir, un visiteur regarde vos projets et veut savoir si vous faites des extensions. L\'assistant répond avec vos mots.<br><em>Conseil : l\'assistant ne répond que sur ce que vous avez validé. Rassurez sur ce point.</em></li><li>Il recueille le programme, la surface et la commune, puis vous transmet une demande déjà qualifiée.<br><em>Conseil : qualifié veut dire : vous savez si ça vaut un rendez-vous.</em></li><li>Quand la question dépasse son périmètre, il passe la main avec un résumé. Vous rappelez en sachant de quoi il s\'agit.<br><em>Conseil : le passage à l\'humain est le point qui fait signer les architectes.</em></li></ul>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('arg-chatbot-ia-artisans-btp', 'argumentaire', (SELECT id FROM sectors WHERE slug = 'artisans-btp'), NULL, (SELECT id FROM services WHERE slug = 'chatbot-ia'), 'Argumentaire — Chatbot IA · Artisans et BTP', '<p>Ce que ça change concrètement chez ce type d\'entreprise :</p><ul><li>Un particulier qui visite votre site le dimanche soir pose trois questions. L\'assistant répond à sa place, tout de suite.<br><em>Conseil : le dimanche soir est le moment où les particuliers font leurs recherches.</em></li><li>Il demande la commune, le type de travaux et le délai souhaité. Vous recevez des demandes triées.<br><em>Conseil : c\'est le tri qui fait gagner du temps, pas la conversation.</em></li><li>Il répond uniquement sur votre zone d\'intervention et vos tarifs de départ. Pas d\'engagement de prix.<br><em>Conseil : l\'assistant ne donne jamais de prix ferme. Dites-le clairement.</em></li></ul>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('arg-chatbot-ia-restauration', 'argumentaire', (SELECT id FROM sectors WHERE slug = 'restauration'), NULL, (SELECT id FROM services WHERE slug = 'chatbot-ia'), 'Argumentaire — Chatbot IA · Restauration', '<p>Ce que ça change concrètement chez ce type d\'entreprise :</p><ul><li>Un client demande si vous êtes ouverts le dimanche. L\'assistant répond à 23 h, avec vos vrais horaires.<br><em>Conseil : l\'exemple le plus parlant de tout le catalogue. Gardez-le en premier.</em></li><li>Il prend la réservation et l\'envoie dans votre planning, avec une confirmation automatique.<br><em>Conseil : le client a sa réponse, vous avez la table remplie.</em></li><li>En cas de demande de groupe ou d\'événement privé, il passe la main à un humain.<br><em>Conseil : les demandes de groupes sont les plus rentables : l\'humain doit les voir.</em></li></ul>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('arg-chatbot-ia-services-b2b', 'argumentaire', (SELECT id FROM sectors WHERE slug = 'services-b2b'), NULL, (SELECT id FROM services WHERE slug = 'chatbot-ia'), 'Argumentaire — Chatbot IA · Services B2B', '<p>Ce que ça change concrètement chez ce type d\'entreprise :</p><ul><li>Un prospect arrive sur votre site à 21 h, après avoir comparé trois prestataires. L\'assistant répond et prend le rendez-vous.<br><em>Conseil : en B2B, la réactivité est souvent le critère de choix.</em></li><li>Il qualifie : taille d\'entreprise, besoin, budget approximatif, échéance. Votre commercial arrive préparé.<br><em>Conseil : un commercial qui arrive préparé convertit mieux. C\'est l\'argument à donner.</em></li><li>Il ne promet jamais de prix et ne s\'engage sur rien. Il oriente et transmet.<br><em>Conseil : les promesses de l\'assistant sont limitées volontairement.</em></li></ul>', 40, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('prv-site-web', 'preuve', NULL, NULL, (SELECT id FROM services WHERE slug = 'site-web'), 'Preuves — site web', '<p>Trois choses vérifiables, sans chiffre inventé :</p><ul><li>Notre prix de départ est public : 790 € HT pour un site une page, 1 490 € HT pour un site professionnel. Vous pouvez le vérifier sur notre site avant même de nous appeler.<br><em>Conseil : être vérifiable est plus fort qu\'être convaincant.</em></li><li>Le devis est écrit, détaillé, avec un prix ferme, et sans engagement. Rien ne démarre avant votre accord.<br><em>Conseil : trois mots à retenir : écrit, ferme, sans engagement.</em></li><li>À la livraison, vous repartez avec le code source, les contenus et tous les accès. Le site vous appartient vraiment.<br><em>Conseil : c\'est la réponse à « et si je veux changer de prestataire ? ».</em></li></ul>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('prv-application', 'preuve', NULL, NULL, (SELECT id FROM services WHERE slug = 'application'), 'Preuves — application sur mesure', '<p>Trois choses vérifiables, sans chiffre inventé :</p><ul><li>Les applications sur mesure démarrent à 2 900 € HT. Une application mobile iOS et Android démarre à 3 900 € HT, et une application mobile complète à 7 900 € HT.<br><em>Conseil : ces tarifs sont publics. Citez-les de mémoire, sans hésiter.</em></li><li>Chaque étape est validée avant la suivante : maquettes, prototype, puis développement. Vous voyez le projet avancer.<br><em>Conseil : une livraison par étapes rassure plus qu\'une promesse de délai.</em></li><li>Sur notre site, le simulateur d\'application mobile donne un ordre de prix immédiat, sans engagement.<br><em>Conseil : envoyez le lien : le prospect joue avec l\'outil, il se projette.</em></li></ul>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('prv-automatisation-ia', 'preuve', NULL, NULL, (SELECT id FROM services WHERE slug = 'automatisation-ia'), 'Preuves — automatisation IA', '<p>Trois choses vérifiables, sans chiffre inventé :</p><ul><li>Les automatisations démarrent à 1 500 € HT, les assistants connectés à vos documents à 2 490 € HT. Le devis final dépend uniquement de ce qu\'on automatise.<br><em>Conseil : un tarif de départ annoncé évite la question « c\'est combien » à contretemps.</em></li><li>Nous commençons par un audit du temps perdu : quelles tâches reviennent, combien de fois par semaine. On ne vend pas d\'automatisation sans avoir mesuré.<br><em>Conseil : c\'est la méthode, et elle est vraie : elle est décrite sur notre site.</em></li><li>Chaque automatisation a un contrôle humain avant l\'envoi. Vous validez ce qui part.<br><em>Conseil : le mot « contrôle » désarme la peur de l\'IA qui fait n\'importe quoi.</em></li></ul>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('prv-chatbot-ia', 'preuve', NULL, NULL, (SELECT id FROM services WHERE slug = 'chatbot-ia'), 'Preuves — chatbot IA', '<p>Trois choses vérifiables, sans chiffre inventé :</p><ul><li>Le chatbot démarre à 990 € HT. L\'assistant connecté à vos documents et à votre agenda démarre à 2 490 € HT.<br><em>Conseil : 990 € HT est un point d\'entrée accessible. Dites-le sans le minimiser.</em></li><li>Vous pouvez tester un assistant formé sur votre métier sur notre site : quatre démos, une par secteur, sans inscription.<br><em>Conseil : le meilleur argument est la démo. Proposez-la à la fin de chaque appel.</em></li><li>L\'assistant ne répond que sur vos informations validées. Il ne promet jamais de prix et passe la main à un humain quand il faut.<br><em>Conseil : trois limites, dites dans cet ordre : c\'est rassurant et honnête.</em></li></ul>', 40, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('tar-site-web', 'tarif', NULL, NULL, (SELECT id FROM services WHERE slug = 'site-web'), 'Tarif — site web', '<p>« Le point de départ, c\'est <strong>790 € HT</strong>. C\'est un tarif de départ, pas un prix au hasard : il correspond à un périmètre précis.</p><p><strong>Ce que ça comprend :</strong></p><ul><li>un site une page, prêt pour le mobile</li><li>le formulaire de contact qualifié</li><li>la mise en ligne et le nom de domaine</li></ul><p><strong>Ce que ça ne comprend pas :</strong></p><ul><li>un site professionnel de 6 pages démarre à 1 490 € HT</li><li>un site sur mesure, avec espace client ou blog, démarre à 2 900 € HT</li><li>l\'hébergement et le nom de domaine sont chiffrés à part dans le devis, jamais cachés</li></ul><p><strong>Et le devis :</strong> écrit, détaillé, gratuit, sans engagement. Pour votre cas, je pense au forfait professionnel. Je vous l\'envoie aujourd\'hui, vous le lisez tranquillement.</p><br><em>Conseil : annoncez le prix sans vous excuser, puis taisez-vous. La première réaction n\'est pas la décision.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('tar-application', 'tarif', NULL, NULL, (SELECT id FROM services WHERE slug = 'application'), 'Tarif — application sur mesure', '<p>« Le point de départ, c\'est <strong>2900 € HT</strong>. C\'est un tarif de départ, pas un prix au hasard : il correspond à un périmètre précis.</p><p><strong>Ce que ça comprend :</strong></p><ul><li>les maquettes et le prototype cliquable</li><li>le développement de la première version</li><li>la formation de vos équipes</li></ul><p><strong>Ce que ça ne comprend pas :</strong></p><ul><li>un site web métier complet démarre à 7 900 € HT</li><li>une application mobile iOS et Android démarre à 3 900 € HT</li><li>le paiement peut se faire en trois fois sur les projets</li></ul><p><strong>Et le devis :</strong> il est écrit, détaillé, gratuit et sans engagement. Le périmètre sera écrit noir sur blanc dans le devis, avec le prix exact. On peut commencer par un module seul, pour limiter le risque.</p><br><em>Conseil : annoncez le prix sans vous excuser, puis taisez-vous. La première réaction n\'est pas la décision.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('tar-automatisation-ia', 'tarif', NULL, NULL, (SELECT id FROM services WHERE slug = 'automatisation-ia'), 'Tarif — automatisation IA', '<p>« Le point de départ, c\'est <strong>1500 € HT</strong>. C\'est un tarif de départ, pas un prix au hasard : il correspond à un périmètre précis.</p><p><strong>Ce que ça comprend :</strong></p><ul><li>l\'audit des tâches répétitives</li><li>la mise en place de la première automatisation</li><li>la surveillance et les alertes en cas de panne</li></ul><p><strong>Ce que ça ne comprend pas :</strong></p><ul><li>les assistants connectés à vos documents démarrent à 2 490 € HT</li><li>les projets data démarrent à 1 900 € HT</li><li>la maintenance démarre à 49 € par mois, sans engagement</li></ul><p><strong>Et le devis :</strong> il est écrit, détaillé, gratuit et sans engagement. Avant de parler budget, on fait l\'audit. Si l\'automatisation ne se rentabilise pas, je vous le dirai franchement.</p><br><em>Conseil : annoncez le prix sans vous excuser, puis taisez-vous. La première réaction n\'est pas la décision.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('tar-chatbot-ia', 'tarif', NULL, NULL, (SELECT id FROM services WHERE slug = 'chatbot-ia'), 'Tarif — chatbot IA', '<p>« Le point de départ, c\'est <strong>990 € HT</strong>. C\'est un tarif de départ, pas un prix au hasard : il correspond à un périmètre précis.</p><p><strong>Ce que ça comprend :</strong></p><ul><li>le chatbot installé sur votre site</li><li>les réponses aux questions fréquentes</li><li>l\'historique des conversations</li></ul><p><strong>Ce que ça ne comprend pas :</strong></p><ul><li>l\'assistant connecté à vos documents et à votre agenda démarre à 2 490 € HT</li><li>l\'automatisation des tâches démarre à 1 500 € HT</li><li>la mise en service se fait en une à deux semaines pour le forfait de départ</li></ul><p><strong>Et le devis :</strong> il est écrit, détaillé, gratuit et sans engagement. 990 € HT, c\'est le point de départ. Vous pouvez tester une démo gratuite avant même de décider. Ça vous dit que je vous envoie le lien ?</p><br><em>Conseil : annoncez le prix sans vous excuser, puis taisez-vous. La première réaction n\'est pas la décision.</em>', 40, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('cta-site-web-premier-appel', 'appel_action', NULL, (SELECT id FROM stages WHERE slug = 'premier-appel'), (SELECT id FROM services WHERE slug = 'site-web'), 'Site web — appeler à l\'action (premier appel)', '<ul><li>Je vous propose une chose simple : l\'audit gratuit de votre site actuel. Une note sur 100, ce qui bloque, et un PDF à garder.<br><em>Conseil : c\'est gratuit et sans engagement. Dites-le avant que le client ne le demande.</em></li><li>Je peux aussi vous envoyer le simulateur de budget : vous choisissez les pages, il donne un ordre de prix tout de suite.<br><em>Conseil : envoyez le lien pendant l\'appel, pas « plus tard ». Le client l\'ouvre souvent aussitôt.</em></li><li>Ou quinze minutes en visio cette semaine, pour regarder ensemble ce qui manque à votre site.<br><em>Conseil : proposez deux créneaux précis, jamais « quand vous voulez ».</em></li></ul><br><em>Conseil : Prenez l\'engagement le plus petit possible. Un audit gratuit ouvre plus de portes qu\'un rendez-vous d\'une heure.</em>', 10, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('cta-site-web-relance', 'appel_action', NULL, (SELECT id FROM stages WHERE slug = 'relance'), (SELECT id FROM services WHERE slug = 'site-web'), 'Site web — appeler à l\'action (relance)', '<ul><li>On reprend là où on s\'était arrêtés : vous alliez regarder le devis et me dire ce qui coince.<br><em>Conseil : rappelez la date du dernier échange, ça prouve que vous suivez le dossier.</em></li><li>Si le prix est le sujet, je peux découper en deux étapes : la page d\'accueil d\'abord, le reste ensuite.<br><em>Conseil : découper réduit le risque perçu. C\'est souvent ce qui débloque.</em></li><li>Dites-moi une date : je vous rappelle jeudi à 11 h, ou mardi à 15 h ?<br><em>Conseil : après avoir proposé deux créneaux, écrivez la date dans la note de l\'appel.</em></li></ul><br><em>Conseil : En relance, le but n\'est pas de convaincre à nouveau : c\'est de fixer la prochaine étape, datée.</em>', 20, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('cta-site-web-closing', 'appel_action', NULL, (SELECT id FROM stages WHERE slug = 'closing'), (SELECT id FROM services WHERE slug = 'site-web'), 'Site web — appeler à l\'action (closing)', '<ul><li>Je récapitule : un site professionnel de six pages, la mise en ligne, et le formulaire de contact. Prix du devis, sans surprise.<br><em>Conseil : trois éléments, pas six. Un récapitulatif trop long rouvre le débat.</em></li><li>Il ne reste que votre accord. Je vous envoie le devis à signer maintenant, ou vous préférez demain matin ?<br><em>Conseil : deux options, aucune n\'étant « plus tard ». C\'est ce qui fait avancer.</em></li></ul><br><em>Conseil : Le closing ne sert pas à re-vendre. Il sert à retirer le dernier obstacle et à fixer la date.</em>', 30, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('cta-application-premier-appel', 'appel_action', NULL, (SELECT id FROM stages WHERE slug = 'premier-appel'), (SELECT id FROM services WHERE slug = 'application'), 'Application — appeler à l\'action (premier appel)', '<ul><li>Avant de parler d\'application, je vous propose un appel de quinze minutes pour comprendre comment vous travaillez aujourd\'hui.<br><em>Conseil : on ne chiffre pas une application sans avoir vu le processus. Dites-le.</em></li><li>Si vous préférez, je vous envoie le simulateur : vous choisissez les écrans, il donne un budget de départ immédiat.<br><em>Conseil : le simulateur dédramatise le prix avant même le premier rendez-vous.</em></li><li>Et si le sujet est plus simple, l\'audit gratuit de votre site reste possible : c\'est souvent par là qu\'on commence.<br><em>Conseil : proposer plusieurs portes d\'entrée évite le « tout ou rien ».</em></li></ul><br><em>Conseil : Une application fait peur par son budget. Le premier pas doit être petit : un échange, un simulateur, un audit.</em>', 40, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('cta-application-relance', 'appel_action', NULL, (SELECT id FROM stages WHERE slug = 'relance'), (SELECT id FROM services WHERE slug = 'application'), 'Application — appeler à l\'action (relance)', '<ul><li>On avait parlé de remplacer vos tableurs. Est-ce que le besoin est toujours là, ou la période a changé ?<br><em>Conseil : poser la question du besoin, pas du projet. Un besoin qui reste est un projet qui revient.</em></li><li>Je peux vous proposer une première version limitée à votre module le plus douloureux, pour démarrer plus petit.<br><em>Conseil : le prototype démarre à 2 900 € HT. C\'est un vrai point d\'entrée, pas un argument.</em></li><li>On se cale vingt minutes avec la personne qui utilise l\'outil tous les jours ?<br><em>Conseil : impliquer un utilisateur, pas seulement le dirigeant. C\'est lui qui validera l\'outil.</em></li></ul><br><em>Conseil : En relance d\'application, le frein est presque toujours le budget. Découper est la meilleure réponse.</em>', 50, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('cta-application-closing', 'appel_action', NULL, (SELECT id FROM stages WHERE slug = 'closing'), (SELECT id FROM services WHERE slug = 'application'), 'Application — appeler à l\'action (closing)', '<ul><li>Le prototype est validé, le périmètre est écrit. On peut démarrer le développement lundi.<br><em>Conseil : un démarrage daté vaut mieux qu\'un « on y va ».</em></li><li>Vous validez chaque étape avant la suivante : rien ne vous engage au-delà de ce que vous avez vu.<br><em>Conseil : c\'est la phrase qui rassure le plus en closing. Gardez-la pour la fin.</em></li><li>Je vous envoie le devis à signer. Le paiement peut se faire en trois fois, sans frais supplémentaires.<br><em>Conseil : ne dites pas « sans frais » si ce n\'est pas écrit dans le devis. Vérifiez avant.</em></li></ul><br><em>Conseil : Au closing, rappelez la livraison par étapes. C\'est ce qui fait signer les projets à plusieurs milliers d\'euros.</em>', 60, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('cta-automatisation-ia-premier-appel', 'appel_action', NULL, (SELECT id FROM stages WHERE slug = 'premier-appel'), (SELECT id FROM services WHERE slug = 'automatisation-ia'), 'Automatisation — appeler à l\'action (premier appel)', '<ul><li>Je vous propose l\'audit du temps perdu : on liste ensemble les tâches qui reviennent, et je vous dis ce qui peut disparaître.<br><em>Conseil : c\'est un audit, pas un devis déguisé. Présentez-le comme tel.</em></li><li>Si vous préférez voir avant, l\'automatisation démarre à 1 500 € HT : vous saurez tout de suite dans quelle fourchette vous êtes.<br><em>Conseil : annoncer le prix tôt évite une conversation de vingt minutes pour rien.</em></li><li>On peut faire ça par téléphone en vingt minutes, ou en visio si vous voulez montrer vos outils.<br><em>Conseil : la visio est souvent plus efficace, le client montre son écran.</em></li></ul><br><em>Conseil : L\'automatisation se vend par l\'audit, pas par la démonstration technique.</em>', 70, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('cta-automatisation-ia-relance', 'appel_action', NULL, (SELECT id FROM stages WHERE slug = 'relance'), (SELECT id FROM services WHERE slug = 'automatisation-ia'), 'Automatisation — appeler à l\'action (relance)', '<ul><li>Vous m\'aviez parlé des relances de devis qui n\'étaient jamais faites. On peut commencer par cette seule tâche.<br><em>Conseil : reprendre une seule tâche concrète rend le projet tangible.</em></li><li>Le devis pour cette partie serait beaucoup plus petit que celui du projet complet.<br><em>Conseil : annoncer un devis plus petit est une bonne nouvelle. Dites-le franchement.</em></li><li>On se donne vingt minutes jeudi pour lister les trois tâches à automatiser en premier ?<br><em>Conseil : trois tâches, pas dix. Un premier lot trop large ne se termine jamais.</em></li></ul><br><em>Conseil : En relance, réduisez le périmètre. Une automatisation livrée vaut mieux qu\'un projet reporté.</em>', 80, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('cta-automatisation-ia-closing', 'appel_action', NULL, (SELECT id FROM stages WHERE slug = 'closing'), (SELECT id FROM services WHERE slug = 'automatisation-ia'), 'Automatisation — appeler à l\'action (closing)', '<ul><li>On démarre par les relances de devis. Mise en place en deux à trois semaines, puis on regarde ce qui reste.<br><em>Conseil : donner une durée, même indicative, rassure plus qu\'un « rapidement ».</em></li><li>Vous gardez le contrôle : chaque message part après votre validation, pendant les premières semaines.<br><em>Conseil : proposer un contrôle humain au démarrage réduit nettement la peur.</em></li><li>Je vous envoie le devis à signer aujourd\'hui, et on planifie l\'atelier de lancement.<br><em>Conseil : un atelier de lancement daté transforme un devis en projet.</em></li></ul><br><em>Conseil : Le closing d\'automatisation se joue sur la confiance, pas sur la technique. Restez concret.</em>', 90, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('cta-chatbot-ia-premier-appel', 'appel_action', NULL, (SELECT id FROM stages WHERE slug = 'premier-appel'), (SELECT id FROM services WHERE slug = 'chatbot-ia'), 'Chatbot — appeler à l\'action (premier appel)', '<ul><li>Le plus simple : testez la démo gratuite sur notre site. Elle existe pour votre secteur, sans inscription, en deux minutes.<br><em>Conseil : c\'est l\'argument le plus fort du catalogue. Proposez-le systématiquement.</em></li><li>Si la démo vous parle, on regarde ensemble les questions qui reviennent chez vous, et on construit l\'assistant dessus.<br><em>Conseil : trois ou quatre questions suffisent pour un premier assistant utile.</em></li><li>En attendant, je peux vous envoyer le lien par mail tout de suite, avec les tarifs de départ.<br><em>Conseil : demandez l\'adresse mail pendant l\'appel. Après, le taux de réponse chute.</em></li></ul><br><em>Conseil : La démo fait le travail à votre place. Ne la remplacez pas par une explication technique.</em>', 100, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('cta-chatbot-ia-relance', 'appel_action', NULL, (SELECT id FROM stages WHERE slug = 'relance'), (SELECT id FROM services WHERE slug = 'chatbot-ia'), 'Chatbot — appeler à l\'action (relance)', '<ul><li>Avez-vous pu tester la démo ? Si oui, qu\'est-ce qui vous a plu, et qu\'est-ce qui vous a manqué ?<br><em>Conseil : les deux questions ensemble. La seconde est la plus utile.</em></li><li>Si l\'assistant doit répondre sur vos documents, on passe au forfait connecté, mais on peut démarrer par les questions fréquentes.<br><em>Conseil : commencer petit, quitte à compléter dans trois mois.</em></li><li>On peut faire un test réel sur votre site pendant une semaine, sur une seule page. Ça vous irait ?<br><em>Conseil : ne promettez pas de test gratuit si ce n\'est pas validé en interne. Vérifiez avant de proposer.</em></li></ul><br><em>Conseil : En relance de chatbot, repartez de la démo. C\'est ce dont le client se souvient.</em>', 110, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('cta-chatbot-ia-closing', 'appel_action', NULL, (SELECT id FROM stages WHERE slug = 'closing'), (SELECT id FROM services WHERE slug = 'chatbot-ia'), 'Chatbot — appeler à l\'action (closing)', '<ul><li>Le contenu de l\'assistant est validé par vous, question par question. Il ne dira rien que vous n\'ayez approuvé.<br><em>Conseil : c\'est la phrase qui fait signer. Mettez-la avant le prix.</em></li><li>Mise en service en une à deux semaines pour le forfait de départ. On regarde les conversations ensemble la première semaine.<br><em>Conseil : proposer un suivi de la première semaine rassure beaucoup.</em></li><li>Je vous envoie le devis à signer. Vous voulez qu\'on fixe la date de mise en ligne maintenant ?<br><em>Conseil : fixer la date avant l\'envoi du devis accélère la signature.</em></li></ul><br><em>Conseil : Le closing de chatbot se joue sur la peur de l\'erreur. Promettez le contrôle, pas la perfection.</em>', 120, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('cta-*-premier-appel', 'appel_action', NULL, (SELECT id FROM stages WHERE slug = 'premier-appel'), NULL, 'Appel à l\'action — premier appel', '<ul><li>Je vous propose une première étape simple, gratuite et sans engagement : l\'audit de votre site, avec une note sur 100.<br><em>Conseil : une étape minuscule fait accepter beaucoup plus facilement la suivante.</em></li><li>Ou quinze minutes de visio pour regarder votre situation ensemble, sans rien vendre.<br><em>Conseil : « sans rien vendre » doit être vrai. C\'est ce qui rend la phrase crédible.</em></li></ul><br><em>Conseil : Choisissez l\'étape la plus petite possible. C\'est elle qui crée le second appel.</em>', 130, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('cta-*-relance', 'appel_action', NULL, (SELECT id FROM stages WHERE slug = 'relance'), NULL, 'Appel à l\'action — relance', '<ul><li>On reprend là où on s\'était arrêtés, et on fixe une date pour la suite.<br><em>Conseil : sans date, une relance est un appel perdu.</em></li><li>Jeudi à 11 h ou mardi à 15 h : qu\'est-ce qui vous arrange le mieux ?<br><em>Conseil : deux créneaux, pas trois. Trois, c\'est déjà une hésitation.</em></li></ul><br><em>Conseil : Une relance réussie se mesure au rendez-vous suivant, pas à la longueur de l\'appel.</em>', 140, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('cta-*-closing', 'appel_action', NULL, (SELECT id FROM stages WHERE slug = 'closing'), NULL, 'Appel à l\'action — closing', '<ul><li>Je récapitule en trois phrases, et vous me dites si j\'ai bon.<br><em>Conseil : le récapitulatif fait dire « oui » trois fois au client.</em></li><li>Il ne reste que la date de démarrage. On la fixe maintenant ?<br><em>Conseil : une date de démarrage est plus facile à accepter qu\'un « accord de principe ».</em></li></ul><br><em>Conseil : Au closing, une seule question à la fois. Deux questions, plus de réponse.</em>', 150, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('fin-rdv', 'conclusion', NULL, NULL, NULL, 'Rendez-vous pris', '<p>Parfait, {contact}. Je note notre rendez-vous et je vous envoie une confirmation par mail dans la journée.</p><ul><li>Récapitulez la date et l\'heure à voix haute, une seule fois</li><li>Demandez qui d\'autre doit être là</li><li>Terminez par un merci simple</li></ul><br><em>Conseil : un rendez-vous confirmé à l\'oral est un rendez-vous tenu. Ne raccrochez pas sans avoir répété la date.</em>', 1, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('fin-devis', 'conclusion', NULL, NULL, NULL, 'Devis demandé', '<p>Très bien, {contact}. Je vous prépare le devis écrit et je vous l\'envoie aujourd\'hui ou demain au plus tard.</p><ul><li>Confirmez l\'adresse mail pendant l\'appel</li><li>Annoncez ce que le devis contiendra, en deux points</li><li>Dites clairement qu\'il est sans engagement</li></ul><br><em>Conseil : « sans engagement » rassure à ce moment précis. Placez-le dans la dernière phrase.</em>', 2, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('fin-rappeler', 'conclusion', NULL, NULL, NULL, 'À rappeler', '<p>Pas de souci, {contact}. Je vous rappelle la semaine prochaine à la même heure. Si ce n\'est pas bon, un mail suffit pour décaler.</p><ul><li>Notez la date dans le journal avant de raccrocher</li><li>Laissez le choix : « si ce n\'est pas bon » évite le rendez-vous forcé</li></ul><br><em>Conseil : une date de rappel sans note est une promesse perdue. Le journal a un champ prévu pour ça.</em>', 3, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('fin-pas_interesse', 'conclusion', NULL, NULL, NULL, 'Pas intéressé', '<p>C\'est très clair, {contact}, et je vous remercie de me l\'avoir dit franchement.</p><ul><li>Ne cherchez pas à convaincre : un non clair se respecte</li><li>Demandez simplement si vous pouvez reprendre contact dans un an</li><li>Remerciez et raccrochez</li></ul><br><em>Conseil : un refus bien accueilli revient souvent un an plus tard. Un refus forcé ne revient jamais.</em>', 4, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('fin-injoignable', 'conclusion', NULL, NULL, NULL, 'Injoignable', '<p>Vous êtes bien sur la messagerie de {entreprise_client}. Je rappellerai un autre jour.</p><ul><li>N\'insistez pas plus de deux fois sur la même semaine</li><li>Essayez un autre créneau : tôt le matin ou en fin de journée</li></ul><br><em>Conseil : un répondeur saturé ne sert à rien. Un message court et daté, oui.</em>', 5, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO speech_blocks (code, type, sector_id, stage_id, service_id, title, content, position, is_active) VALUES ('fin-ne_plus_rappeler', 'conclusion', NULL, NULL, NULL, 'Ne plus rappeler', '<p>Je comprends très bien, {contact}. Je note que vous ne souhaitez plus être contacté et je vous en fais la promesse : vous ne recevrez plus d\'appel de notre part.</p><ul><li>Ne cherchez pas à obtenir une dernière information</li><li>Confirmez que l\'opposition est enregistrée</li><li>Remerciez pour le temps accordé et raccrochez</li></ul><br><em>Conseil : cette phrase doit être dite lentement et sans amertume. C\'est aussi ce qui protège l\'entreprise.</em>', 6, 1) ON DUPLICATE KEY UPDATE type = VALUES(type), sector_id = VALUES(sector_id), stage_id = VALUES(stage_id), service_id = VALUES(service_id), title = VALUES(title), content = VALUES(content), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-j-ai-d-j-un-site-et-il-me-suffit', 'J\'ai déjà un site, et il me suffit.', '<p>Vous avez raison de le protéger : c\'est votre vitrine.</p>\n- Une question simple : il vous apporte combien de demandes par mois ?\n- Si la réponse est « aucune », ce n\'est pas un site, c\'est une carte de visite\n- On ne refait pas tout : l\'audit gratuit dit si quelques corrections suffisent\n\n<p>Quand vous voulez, je vous envoie la note sur 100. Vous serez fixé en dix minutes.</p>\n\n<em>Conseil : ne critiquez jamais le site existant. Le client l\'a choisi.</em>', NULL, NULL, 1, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-j-ai-d-j-un-prestataire-a-se-passe-bien', 'J\'ai déjà un prestataire, ça se passe bien.', '<p>Tant mieux, un prestataire de confiance, ça ne se remplace pas.</p>\n- Je ne suis pas là pour le déloger. Juste pour être un second avis si besoin\n- Le devis écrit et le simulateur de budget sont gratuits : ça vous donne un point de comparaison\n- Beaucoup de clients nous appellent pour une seule brique qu\'il ne fait pas\n\n<p>Je vous laisse le lien de l\'audit gratuit. Si un jour le sujet revient, vous aurez un repère.</p>\n\n<em>Conseil : accepter le prestataire en place évite de transformer l\'appel en procès.</em>', NULL, NULL, 2, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-c-est-trop-cher-pour-moi', 'C\'est trop cher pour moi.', '<p>Je comprends, et c\'est une vraie question.</p>\n- Ce n\'est peut-être pas le bon moment : le tarif de départ pour un site commence à 790 € HT\n- On peut démarrer par une seule page, puis compléter dans six mois\n- Le devis écrit est gratuit : il vous donne un chiffre exact, pas une fourchette\n\n<p>Quel budget aviez-vous en tête, même approximatif ? Ça m\'évite de vous proposer à côté.</p>\n\n<em>Conseil : « c\'est trop cher » veut souvent dire « je ne vois pas la valeur ». Faites parler du besoin avant du prix.</em>', NULL, NULL, 3, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-envoyez-moi-un-mail-je-regarderai', 'Envoyez-moi un mail, je regarderai.', '<p>Avec plaisir, je vous envoie ça aujourd\'hui.</p>\n- Pour que le mail soit utile : c\'est plutôt sur le site ou sur vos demandes entrantes ?\n- Je mets deux exemples de votre secteur et les tarifs de départ\n- Et je vous rappelle jeudi, le temps de le lire tranquillement\n\n<p>Vous êtes joignable en fin de matinée ou plutôt en fin d\'après-midi ?</p>\n\n<em>Conseil : un mail sans créneau de rappel est un mail perdu. Toujours fixer la suite.</em>', NULL, NULL, 4, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-je-n-ai-pas-le-temps-l', 'Je n\'ai pas le temps, là.', '<p>Je comprends, je vous prends deux minutes maximum, ou je vous rappelle.</p>\n- Une seule question, et je raccroche : vous recevez combien de demandes par semaine ?\n- Si le sujet n\'est pas pour maintenant, dites-le moi franchement\n- Sinon, je vous rappelle en fin de journée ou demain matin\n\n<p>Qu\'est-ce qui est le plus simple pour vous ?</p>\n\n<em>Conseil : ne dites jamais « deux minutes » puis parlez dix. La prochaine fois, personne ne répond.</em>', NULL, NULL, 5, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-rappelez-moi-plus-tard-je-suis-d-bord', 'Rappelez-moi plus tard, je suis débordé.', '<p>Pas de problème, je préfère ça à un appel bâclé.</p>\n- Je peux vous rappeler jeudi à 11 h, ou mardi en fin de journée ?\n- Si la période est chargée, on peut se donner rendez-vous le mois prochain\n- En attendant, je vous laisse un mail court avec l\'essentiel\n\n<p>Dites-moi simplement le créneau qui vous arrange.</p>\n\n<em>Conseil : notez la date dans le journal de l\'appel. Un rappel non noté est un rappel oublié.</em>', NULL, NULL, 6, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-je-dois-en-parler-mon-associ-ma-femme', 'Je dois en parler à mon associé / à ma femme.', '<p>Bien sûr, c\'est une décision à deux, c\'est normal.</p>\n- Est-ce qu\'il ou elle a des questions types sur ce genre de projet ?\n- Je peux vous envoyer un résumé d\'une page, écrit pour être montré\n- Et on peut faire un point à trois, quinze minutes, sans que je reprenne tout\n\n<p>Je vous rappelle jeudi, une fois que vous en aurez parlé ?</p>\n\n<em>Conseil : ne demandez pas « quand pourrez-vous en parler », demandez « comment vous en parlez d\'habitude ».</em>', NULL, NULL, 7, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj--a-ne-m-int-resse-pas', 'Ça ne m\'intéresse pas.', '<p>C\'est clair, je vous remercie de me le dire.</p>\n- Une dernière chose, et je vous laisse : c\'est le sujet qui ne vous intéresse pas, ou le moment ?\n- Si c\'est le moment, je peux reprendre contact dans six mois\n- Si c\'est le sujet, dites-le moi aussi : ça m\'évitera de vous déranger\n\n<p>Dans les deux cas, je note et je respecte.</p>\n\n<em>Conseil : distinguer « pas le sujet » et « pas le moment » évite de rayer un bon prospect.</em>', NULL, NULL, 8, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-on-n-a-pas-besoin-de-a-on-a-d-j-assez-de-clients', 'On n\'a pas besoin de ça, on a déjà assez de clients.', '<p>C\'est une bonne situation, peu d\'entreprises peuvent le dire.</p>\n- Dans ce cas, la question n\'est pas d\'avoir plus de clients, mais de choisir lesquels\n- Un site clair filtre les demandes : les mauvaises questions arrivent moins\n- Et il vous fait gagner du temps sans amener un seul client de plus\n\n<p>Qu\'est-ce qui vous coûte le plus de temps aujourd\'hui, justement ?</p>\n\n<em>Conseil : basculez du « plus de clients » au « moins de temps perdu ». C\'est le même produit, un autre angle.</em>', NULL, NULL, 9, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-je-ne-comprends-rien-l-informatique', 'Je ne comprends rien à l\'informatique.', '<p>Rassurez-vous, c\'est nous qui parlons technique, pas vous.</p>\n- Vous décrivez votre métier, on traduit\n- Vous n\'aurez jamais de réunion sur des sujets techniques\n- À la livraison, on vous montre trois gestes : modifier un texte, ajouter une photo, publier\n\n<p>Et si vous préférez ne rien toucher, la maintenance commence à 49 € par mois, sans engagement.</p>\n\n<em>Conseil : ne minimisez pas (« c\'est simple »). Reconnaissez, puis rassurez avec des gestes très concrets.</em>', NULL, NULL, 10, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-je-me-suis-d-j-fait-avoir-par-un-prestataire', 'Je me suis déjà fait avoir par un prestataire.', '<p>Je comprends, et malheureusement vous n\'êtes pas le seul.</p>\n- Chez nous, les prix de départ sont publics : vous les voyez avant de nous parler\n- Le devis écrit fixe le prix exact et le périmètre, sans surprise\n- À la livraison, le code source et tous les accès vous appartiennent\n\n<p>Vous ne dépendez de personne, y compris de nous. Ça change la relation.</p>\n\n<em>Conseil : la remise du code et des accès est votre meilleur argument face à une mauvaise expérience.</em>', NULL, NULL, 11, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-vous-tes-qui-exactement', 'Vous êtes qui exactement ?', '<p>Bonne question, je me présente mieux.</p>\n- Prime Vision Solutions, une agence digitale qui travaille avec des TPE et des PME\n- Notre site est public : prestations, tarifs de départ, exemples de projets\n- Un seul interlocuteur du premier échange à la livraison\n\n<p>Je vous envoie le lien tout de suite, vous jugez par vous-même.</p>\n\n<em>Conseil : donnez le site et le téléphone de l\'entreprise. Un commercial qui se cache n\'inspire pas confiance.</em>', NULL, NULL, 12, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-comment-vous-avez-eu-mon-num-ro', 'Comment vous avez eu mon numéro ?', '<p>Question légitime, je vous réponds franchement.</p>\n- Votre entreprise figure dans un annuaire professionnel public\n- Nous appelons des entreprises de votre secteur, pas des particuliers\n- Si vous ne souhaitez plus d\'appel, dites-le moi : je le note et je ne rappelle pas\n\n<p>Voulez-vous que je vous retire de notre liste dès maintenant ?</p>\n\n<em>Conseil : proposer le retrait soi-même désarme complètement la méfiance. Et c\'est la bonne chose à faire.</em>', NULL, NULL, 13, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-je-pr-f-re-un-prestataire-local-je-veux-pouvoir-le-voir', 'Je préfère un prestataire local, je veux pouvoir le voir.', '<p>C\'est compréhensible, on travaille mieux avec quelqu\'un qu\'on peut joindre.</p>\n- Nos rendez-vous se font en visio, avec partage d\'écran : c\'est souvent plus concret qu\'un rendez-vous en agence\n- Vous avez un interlocuteur unique, joignable, pas un service client\n- Et les livraisons se font par étapes : vous voyez le travail avant de payer la suite\n\n<p>On peut faire un premier point de quinze minutes en visio, vous verrez si le courant passe.</p>\n\n<em>Conseil : la proximité est souvent un prétexte. La vraie question est « est-ce que je serai suivi ».</em>', NULL, NULL, 14, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-je-peux-le-faire-moi-m-me-ou-mon-neveu-s-en-occupe', 'Je peux le faire moi-même, ou mon neveu s\'en occupe.', '<p>Tant mieux, c\'est une vraie chance d\'avoir quelqu\'un qui touche à ça.</p>\n- Une question : combien de temps ça vous prend, et qu\'est-ce qui bloque depuis six mois ?\n- Souvent, le site existe, mais il n\'est pas fini ou pas à jour\n- On peut faire uniquement ce qui bloque : les photos, la page contact, la vitesse\n\n<p>Ça vaut peut-être le coup de savoir ce qui manque précisément, non ?</p>\n\n<em>Conseil : ne dénigrez jamais le neveu. Proposez de compléter, pas de remplacer.</em>', NULL, NULL, 15, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-je-n-ai-pas-de-budget-en-ce-moment', 'Je n\'ai pas de budget en ce moment.', '<p>Je comprends, et je préfère le savoir tout de suite.</p>\n- Le devis écrit est gratuit : il vous donne un chiffre exact pour plus tard\n- Si le budget est bloqué, on peut découper en deux ou trois étapes étalées dans l\'année\n- Certains projets démarrent à 790 € HT, ce n\'est pas le prix d\'une refonte complète\n\n<p>Quand votre prochaine fenêtre budgétaire s\'ouvre, je vous rappelle ?</p>\n\n<em>Conseil : ne forcez pas. Notez la période budgétaire dans le journal : c\'est un rappel à programmer.</em>', NULL, NULL, 16, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-arr-tez-de-m-appeler-ne-me-rappelez-plus', 'Arrêtez de m\'appeler, ne me rappelez plus.', '<p>Je comprends parfaitement, {contact}. Je note dès maintenant que vous ne souhaitez plus être contacté.</p>\n- Vous ne recevrez plus d\'appel de notre part\n- Je vous remercie de me l\'avoir dit clairement\n- Je vous souhaite une bonne journée\n\n<em>Conseil : ne tentez aucune dernière question. Honorez la demande, enregistrez « Ne plus rappeler » et raccrochez.</em>', NULL, NULL, 17, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-mon-site-me-suffit-je-n-ai-pas-de-ventes-en-ligne', 'Mon site me suffit, je n\'ai pas de ventes en ligne.', '<p>C\'est logique : un site vitrine n\'a pas besoin de vendre en ligne.</p>\n- La question, c\'est plutôt : est-ce qu\'il donne envie de vous appeler ?\n- Trois éléments font la différence : vos réalisations, vos tarifs de départ, un moyen de contact visible\n- Et sur téléphone, il doit se lire en dix secondes\n\n<p>Je vous propose l\'audit gratuit : une note sur 100, et vous verrez s\'il manque quelque chose.</p>\n\n<em>Conseil : ne parlez jamais d\'e-commerce à quelqu\'un qui n\'en veut pas. Restez sur « être trouvé » et « rassurer ».</em>', (SELECT id FROM services WHERE slug = 'site-web'), NULL, 18, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-mon-site-est-vieux-mais-il-fonctionne-encore', 'Mon site est vieux mais il fonctionne encore.', '<p>S\'il fonctionne, il n\'y a peut-être rien à refaire.</p>\n- Deux points à vérifier : l\'affichage sur téléphone et la vitesse de chargement\n- Si ces deux points sont bons, on ne touche à rien\n- S\'ils sont mauvais, on corrige seulement ça, sans refonte\n\n<p>L\'audit gratuit répond à ces deux questions en quelques minutes.</p>\n\n<em>Conseil : proposer de ne rien faire est parfois la meilleure façon de gagner un client plus tard.</em>', (SELECT id FROM services WHERE slug = 'site-web'), NULL, 19, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-je-ne-sais-pas-quoi-crire-sur-mon-site', 'Je ne sais pas quoi écrire sur mon site.', '<p>C\'est la remarque la plus fréquente, et ce n\'est pas un problème.</p>\n- On écrit avec vous : on vous pose des questions sur votre métier, on rédige, vous corrigez\n- Vos mots à vous passent d\'abord, on met simplement en forme\n- Les tarifs de départ incluent l\'accompagnement sur les textes\n\n<p>Vous n\'aurez jamais une page blanche devant vous.</p>\n\n<em>Conseil : rassurez sur le processus, pas sur le résultat. Le client veut savoir qu\'il ne sera pas seul.</em>', (SELECT id FROM services WHERE slug = 'site-web'), NULL, 20, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-j-ai-d-j-une-page-facebook-a-suffit', 'J\'ai déjà une page Facebook, ça suffit.', '<p>Une page Facebook, c\'est bien pour les habitués, et c\'est gratuit.</p>\n- Mais quand quelqu\'un cherche votre métier sur Google, il ne tombe pas sur Facebook\n- Un site, c\'est vous qui le possédez : pas de changement d\'algorithme, pas de compte fermé\n- On peut très bien garder la page et ajouter seulement un site simple à côté\n\n<p>Le site ne remplace pas Facebook, il le complète.</p>\n\n<em>Conseil : ne dénigrez pas les réseaux sociaux. Beaucoup de clients y tiennent beaucoup.</em>', (SELECT id FROM services WHERE slug = 'site-web'), NULL, 21, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-combien-de-temps-a-prend-un-site', 'Combien de temps ça prend, un site ?', '<p>Ça dépend du périmètre, et c\'est écrit dans le devis.</p>\n- Un site une page démarre avec un délai indicatif d\'une à deux semaines\n- Un site professionnel de six pages, trois à quatre semaines\n- Le calendrier exact est confirmé dans le devis écrit\n\n<p>La vraie variable, c\'est la disponibilité de vos contenus et de vos photos.</p>\n\n<em>Conseil : ne donnez jamais un délai de mémoire sans ajouter « indicatif, confirmé dans le devis ».</em>', (SELECT id FROM services WHERE slug = 'site-web'), NULL, 22, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-est-ce-que-je-serai-premier-sur-google', 'Est-ce que je serai premier sur Google ?', '<p>Personne d\'honnête ne peut vous le promettre.</p>\n- Ce qu\'on fait, c\'est une base technique propre : structure claire, pages rapides, titres et descriptions\n- C\'est la condition pour être trouvé, pas une garantie de première place\n- Le classement dépend ensuite de la concurrence dans votre ville et du contenu publié\n\n<p>Je préfère vous le dire maintenant que de vous vendre un rêve.</p>\n\n<em>Conseil : cet aveu de franchise fait souvent signer. Ne cédez jamais sur une promesse de position.</em>', (SELECT id FROM services WHERE slug = 'site-web'), NULL, 23, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-une-application-c-est-r-serv-aux-grandes-entreprises', 'Une application, c\'est réservé aux grandes entreprises.', '<p>Je comprends l\'idée, mais ce n\'est plus vrai.</p>\n- On en fait pour des structures de trois à trente personnes\n- Le prototype démarre à 2 900 € HT, avec un seul module\n- On commence petit : remplacer un tableur, c\'est déjà une application\n\n<p>Vous utilisez déjà des tableurs partagés ? C\'est souvent le point de départ.</p>\n\n<em>Conseil : ne parlez jamais d\'« ERP » ou de « plateforme ». Parlez d\'« un seul outil à la place de trois ».</em>', (SELECT id FROM services WHERE slug = 'application'), NULL, 24, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-on-n-a-pas-les-comp-tences-en-interne-pour-utiliser-une-application', 'On n\'a pas les compétences en interne pour utiliser une application.', '<p>Vous n\'en aurez pas besoin.</p>\n- L\'outil est conçu avec les personnes qui l\'utilisent, pas contre elles\n- On forme vos équipes à la livraison, et on reste joignable\n- Vous pouvez aussi prendre la maintenance à partir de 49 € par mois, sans engagement\n\n<p>Si l\'outil n\'est pas simple, c\'est notre conception qui est en cause, pas vos équipes.</p>\n\n<em>Conseil : cette dernière phrase est à retenir mot pour mot. Elle change l\'ambiance de l\'appel.</em>', (SELECT id FROM services WHERE slug = 'application'), NULL, 25, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-c-est-trop-long-mettre-en-place', 'C\'est trop long à mettre en place.', '<p>C\'est vrai que ce n\'est pas un site en une semaine.</p>\n- On livre par étapes : la première version utilisable arrive bien avant la fin du projet\n- Vous validez chaque étape, donc vous ne découvrez rien à la fin\n- Et on peut commencer par un seul module, livré en quelques semaines\n\n<p>Qu\'est-ce qui vous serait le plus utile en premier ?</p>\n\n<em>Conseil : la livraison par étapes est votre meilleure réponse à la peur du projet interminable.</em>', (SELECT id FROM services WHERE slug = 'application'), NULL, 26, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-on-a-d-j-un-logiciel-m-tier-a-ne-sert-rien', 'On a déjà un logiciel métier, ça ne sert à rien.', '<p>Si votre logiciel fait le travail, il faut le garder.</p>\n- La question : est-ce qu\'il communique avec vos autres outils, ou est-ce que vous ressaisissez ?\n- C\'est souvent là qu\'on intervient : faire dialoguer l\'existant\n- On ne remplace pas un logiciel métier, on bouche les trous autour\n\n<p>Qu\'est-ce que vous devez ressaisir à la main aujourd\'hui ?</p>\n\n<em>Conseil : les projets d\'application échouent quand ils remplacent un outil métier. Vendez l\'interconnexion.</em>', (SELECT id FROM services WHERE slug = 'application'), NULL, 27, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj--a-co-te-combien-exactement', 'Ça coûte combien, exactement ?', '<p>Le point de départ est 2 900 € HT pour un prototype, et 7 900 € HT pour une application complète.</p>\n- Ce sont des tarifs de départ : le prix exact dépend du nombre d\'écrans et des connexions\n- Le devis écrit gratuit fixe le montant et ce qui est inclus\n- On peut commencer par un module seul pour rester dans un budget plus serré\n\n<p>Quel budget avez-vous en tête ? Je vous dirai franchement si c\'est jouable.</p>\n\n<em>Conseil : annoncez le prix et taisez-vous. Le silence fait plus de travail que trois arguments.</em>', (SELECT id FROM services WHERE slug = 'application'), NULL, 28, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-et-si-on-veut-changer-plus-tard-on-sera-bloqu', 'Et si on veut changer plus tard ? On sera bloqué.', '<p>Non, et c\'est un engagement écrit de notre part.</p>\n- Le code source vous est remis à la livraison\n- Les accès serveur et nom de domaine vous appartiennent\n- Une autre équipe peut reprendre le projet, sans notre autorisation\n\n<p>Vous ne signez pas un abonnement, vous achetez un outil.</p>\n\n<em>Conseil : proposez de montrer cette clause dans le devis. Un engagement écrit vaut mille promesses.</em>', (SELECT id FROM services WHERE slug = 'application'), NULL, 29, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-l-automatisation-c-est-trop-compliqu-mettre-en-place', 'L\'automatisation, c\'est trop compliqué à mettre en place.', '<p>C\'est souvent l\'image que ça donne, mais la mise en place se fait sans vous.</p>\n- On commence par un audit du temps perdu : quelles tâches reviennent, combien de fois\n- On automatise une seule tâche d\'abord, celle qui coûte le plus\n- Vous validez ce qui part, pendant les premières semaines\n\n<p>Les automatisations démarrent à 1 500 € HT. On peut commencer petit.</p>\n\n<em>Conseil : ne décrivez jamais la plomberie technique. Décrivez la tâche qui disparaît.</em>', (SELECT id FROM services WHERE slug = 'automatisation-ia'), NULL, 30, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-on-ne-sait-pas-ce-qu-on-pourrait-automatiser', 'On ne sait pas ce qu\'on pourrait automatiser.', '<p>C\'est exactement à ça que sert le premier échange.</p>\n- Trois questions suffisent : qu\'est-ce qui revient, qui le fait, combien de temps ça prend\n- On repère souvent deux ou trois tâches très simples, comme les relances de devis\n- Vous repartez avec une liste, même si vous ne nous confiez rien\n\n<p>On peut faire cet audit par téléphone en vingt minutes.</p>\n\n<em>Conseil : un audit offert qui se termine sans devis est un bon investissement. Ne le monnayez pas.</em>', (SELECT id FROM services WHERE slug = 'automatisation-ia'), NULL, 31, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-l-ia-a-fait-des-erreurs-je-ne-veux-pas-de-a', 'L\'IA, ça fait des erreurs, je ne veux pas de ça.', '<p>Vous avez raison de vous méfier, c\'est le vrai sujet.</p>\n- Chaque automatisation a un contrôle humain avant l\'envoi\n- L\'assistant ne répond que sur vos informations validées, jamais au-delà\n- On teste les réponses sur des cas réels avant la mise en service\n\n<p>Rien ne part sans votre accord, au moins pendant les premières semaines.</p>\n\n<em>Conseil : ne dites jamais « ça ne se trompe pas ». Dites « ça ne part pas sans vous ».</em>', (SELECT id FROM services WHERE slug = 'automatisation-ia'), NULL, 32, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-mes-donn-es-elles-vont-o', 'Mes données, elles vont où ?', '<p>Question essentielle, et la réponse est simple.</p>\n- Les données restent dans vos outils ou sur un serveur que vous validez\n- On ne collecte que ce qui est nécessaire au fonctionnement\n- Les règles de conservation sont définies avec vous, conformément au RGPD\n\n<p>Tout est écrit dans le devis avant de commencer, pas après.</p>\n\n<em>Conseil : ne promettez pas « 100 % sécurisé ». Dites ce qui est prévu, noir sur blanc.</em>', (SELECT id FROM services WHERE slug = 'automatisation-ia'), NULL, 33, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj--a-va-me-faire-perdre-des-clients-si-c-est-automatique', 'Ça va me faire perdre des clients si c\'est automatique.', '<p>C\'est une crainte fréquente, et légitime.</p>\n- On n\'automatise pas la relation client, on automatise les tâches répétitives\n- Un devis relancé automatiquement, c\'est un client qui se sent suivi, pas ignoré\n- Un humain peut reprendre la main à tout moment\n\n<p>L\'automatisation remplace la relance oubliée, pas la conversation.</p>\n\n<em>Conseil : donnez un exemple vécu, pas une théorie. « La relance du devis » parle à tout le monde.</em>', (SELECT id FROM services WHERE slug = 'automatisation-ia'), NULL, 34, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-mes-clients-n-aiment-pas-parler-un-robot', 'Mes clients n\'aiment pas parler à un robot.', '<p>C\'est vrai pour beaucoup de gens, et on en tient compte.</p>\n- L\'assistant ne se fait pas passer pour un humain : il est identifié\n- À la moindre demande sensible, il passe la main avec un résumé\n- La plupart des gens préfèrent une réponse à 22 h qu\'aucune réponse\n\n<p>Le but n\'est pas de remplacer la conversation, c\'est d\'éviter le silence.</p>\n\n<em>Conseil : proposez de tester la démo soi-même. L\'expérience vaut mieux que l\'argument.</em>', (SELECT id FROM services WHERE slug = 'chatbot-ia'), NULL, 35, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj--a-va-se-tromper-et-dire-n-importe-quoi', 'Ça va se tromper et dire n\'importe quoi.', '<p>C\'est le risque numéro un, et il se maîtrise.</p>\n- L\'assistant ne répond qu\'à partir de vos informations validées\n- Il ne donne jamais de prix ferme et ne prend aucun engagement\n- Vous relisez et validez chaque réponse avant la mise en service\n\n<p>S\'il ne sait pas, il le dit et passe la main. C\'est prévu.</p>\n\n<em>Conseil : « il ne sait pas, il le dit » est la phrase qui rassure le plus. Gardez-la.</em>', (SELECT id FROM services WHERE slug = 'chatbot-ia'), NULL, 36, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-on-r-pond-d-j-au-t-l-phone-et-par-mail', 'On répond déjà au téléphone et par mail.', '<p>Et c\'est très bien, c\'est le cœur du métier.</p>\n- La question, c\'est le soir et le week-end, quand personne ne répond\n- Et les questions répétitives : horaires, accès, tarifs de départ\n- L\'assistant traite celles-là, vous gardez les vraies conversations\n\n<p>Combien de messages attendez-vous jusqu\'au lendemain matin ?</p>\n\n<em>Conseil : positionnez le chatbot comme un filtre, pas comme un remplaçant.</em>', (SELECT id FROM services WHERE slug = 'chatbot-ia'), NULL, 37, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-on-a-d-j-un-formulaire-de-contact', 'On a déjà un formulaire de contact.', '<p>C\'est déjà une bonne base, tout le monde n\'en a pas.</p>\n- Un formulaire attend une réponse. Un assistant répond tout de suite\n- La différence se voit le soir : le visiteur part, ou il obtient sa réponse\n- Et l\'assistant peut qualifier la demande avant qu\'elle vous arrive\n\n<p>Le formulaire reste : l\'assistant le complète.</p>\n\n<em>Conseil : ne remplacez rien de ce que le client a déjà. Ajoutez.</em>', (SELECT id FROM services WHERE slug = 'chatbot-ia'), NULL, 38, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-990-pour-un-chatbot-a-me-para-t-beaucoup', '990 € pour un chatbot, ça me paraît beaucoup.', '<p>Je comprends, ça se compare à autre chose.</p>\n- C\'est le point de départ : installation, réponses aux questions fréquentes, historique des conversations\n- Ça représente une à deux semaines de mise en service\n- Si vous devez embaucher quelqu\'un pour répondre le soir, le calcul est vite fait\n\n<p>Vous pouvez tester la démo gratuite avant de décider quoi que ce soit.</p>\n\n<em>Conseil : ne défendez pas le prix, comparez-le. Le client fera le calcul lui-même.</em>', (SELECT id FROM services WHERE slug = 'chatbot-ia'), NULL, 39, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-et-si-un-client-pose-une-question-compliqu-e', 'Et si un client pose une question compliquée ?', '<p>Il passe la main, c\'est prévu dès le départ.</p>\n- L\'assistant détecte les demandes hors périmètre : devis complexe, réclamation, cas particulier\n- Il transmet la conversation avec un résumé et les coordonnées\n- Vous rappelez en sachant déjà de quoi il s\'agit\n\n<p>Vous ne perdez pas le client, vous arrivez préparé.</p>\n\n<em>Conseil : le passage à l\'humain est un argument de vente, pas une limite. Présentez-le comme tel.</em>', (SELECT id FROM services WHERE slug = 'chatbot-ia'), NULL, 40, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-je-travaille-par-bouche-oreille-a-me-suffit', 'Je travaille par bouche-à-oreille, ça me suffit.', '<p>C\'est le meilleur signe qu\'une entreprise travaille bien.</p>\n- Le bouche-à-oreille reste votre premier canal, ça ne change pas\n- Mais celui qui vous recommande tape votre nom sur Google avant d\'appeler\n- S\'il ne trouve rien, il doute. Un site simple règle ça\n\n<p>Vos clients vous recommandent, mais qu\'est-ce qu\'ils trouvent en vous cherchant ?</p>\n\n<em>Conseil : ne demandez jamais au client de choisir entre le bouche-à-oreille et le site. Les deux coexistent.</em>', NULL, (SELECT id FROM sectors WHERE slug = 'artisans-btp'), 41, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-mes-clients-r-servent-par-t-l-phone-a-marche-tr-s-bien', 'Mes clients réservent par téléphone, ça marche très bien.', '<p>Bien sûr, et le téléphone reste le canal principal.</p>\n- Le sujet, c\'est le soir et le week-end, quand la salle est pleine ou fermée\n- Un client qui ne joint personne réserve ailleurs\n- La réservation en ligne ne remplace pas le téléphone : elle prend ce que vous ne pouvez pas prendre\n\n<p>Vous perdez combien de demandes le samedi soir, à votre avis ?</p>\n\n<em>Conseil : ne parlez jamais de remplacer le téléphone face à un restaurateur. Parlez des heures creuses.</em>', NULL, (SELECT id FROM sectors WHERE slug = 'restauration'), 42, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-mes-projets-se-vendent-sur-recommandation-pas-sur-internet', 'Mes projets se vendent sur recommandation, pas sur Internet.', '<p>C\'est souvent vrai dans l\'architecture, et c\'est une force.</p>\n- Mais la recommandation se vérifie : on tape votre nom avant de vous appeler\n- Un site avec vos réalisations donne du poids à cette recommandation\n- Et il vous évite d\'envoyer un PDF de vingt pages à chaque nouveau contact\n\n<p>Vos projets sont montrés comment aujourd\'hui ?</p>\n\n<em>Conseil : ne parlez pas de « visibilité », parlez de « crédibilité » et de « gagner du temps ».</em>', NULL, (SELECT id FROM sectors WHERE slug = 'architectes'), 43, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
INSERT INTO objections (code, question, answer, service_id, sector_id, position, is_active) VALUES ('obj-on-vend-surtout-par-appels-d-offres-et-recommandations', 'On vend surtout par appels d\'offres et recommandations.', '<p>C\'est le modèle de beaucoup d\'entreprises de services, et il fonctionne.</p>\n- Le site n\'amène pas toujours l\'appel d\'offres, mais il est regardé avant\n- Une page claire par domaine d\'expertise aide à être retenu sur une short-list\n- Et les relances de devis, elles, s\'appliquent à tous les canaux\n\n<p>Quand vous êtes présélectionné, le client regarde quoi avant de choisir ?</p>\n\n<em>Conseil : en B2B, le site sert souvent à confirmer un choix déjà fait. C\'est un argument suffisant.</em>', NULL, (SELECT id FROM sectors WHERE slug = 'services-b2b'), 44, 1) ON DUPLICATE KEY UPDATE question = VALUES(question), answer = VALUES(answer), service_id = VALUES(service_id), sector_id = VALUES(sector_id), position = VALUES(position), is_active = VALUES(is_active);
